-- Aprenda se Divertindo · 94 · Baralho de cartões · trilha Saúde · mais 500 cartões (total de 1.000)
-- Rode depois do 93-cartoes-fiscal-2.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Assuntos novos, conferidos contra os 4.500 cartões já existentes para não repetir: Enfermagem (Lei 7.498, Cofen 736/2024,
-- sinais vitais, exame físico, cálculos de medicação, feridas, ostomias, nutrição, drenos, ECG, choque, centro cirúrgico, CME,
-- EPIs, imunização, saúde da mulher e da criança, obstetrícia, saúde mental, segurança do paciente), Legislação do SUS
-- (CF, Leis 8.080 e 8.142, Decreto 7.508, LC 141, redes, políticas, vigilância, epidemiologia), Medicina e Fisioterapia.
-- Cartões numerados de 2.000.004.501 a 2.000.005.000. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000004501, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Quais as atribuições do técnico de enfermagem pela Lei 7.498/1986?", "verso": "Atividades de nível médio, como orientação e acompanhamento do trabalho de enfermagem em grau auxiliar e participação no planejamento da assistência, exceto as privativas do enfermeiro.", "explicacao": "Lei 7.498/1986, art. 12."}, {"id": 2000004502, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Quais as atribuições do auxiliar de enfermagem pela Lei 7.498/1986?", "verso": "Atividades de nível médio de natureza repetitiva, sob supervisão, como observar e anotar sinais e sintomas, executar tratamentos prescritos e prestar cuidados de higiene e conforto.", "explicacao": "Lei 7.498/1986, art. 13."}, {"id": 2000004503, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual decreto regulamenta a Lei do Exercício Profissional da Enfermagem?", "verso": "O Decreto 94.406/1987.", "explicacao": "Detalha as atividades de cada categoria."}, {"id": 2000004504, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "Qual resolução do Cofen trata atualmente do processo de enfermagem?", "verso": "A Resolução Cofen 736/2024, que substituiu a 358/2009.", "explicacao": "Organiza o processo em cinco etapas: avaliação, diagnóstico, planejamento, implementação e evolução."}, {"id": 2000004505, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pares", "frente": "Qual a diferença entre anotação de enfermagem e evolução de enfermagem?", "verso": "Anotação: registro de cuidados e observações, feito por toda a equipe. Evolução: análise do enfermeiro sobre as respostas do paciente e o plano de cuidados, privativa dele.", "explicacao": "Registros de enfermagem no prontuário."}, {"id": 2000004506, "trilha": "saude", "materia": "enf", "assunto": "Exercício profissional", "tipo": "pergunta", "frente": "A contenção mecânica de paciente pode ser feita pela equipe de enfermagem?", "verso": "Sim, em situações de risco iminente, sob supervisão do enfermeiro, com prescrição médica (ou registro da urgência) e monitoramento contínuo.", "explicacao": "Resolução Cofen 427/2012."}, {"id": 2000004507, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "O profissional de enfermagem pode participar de prática que viole os direitos humanos, como tortura?", "verso": "Não. É proibido participar de atos de tortura, tratamento cruel ou degradante, mesmo por ordem superior.", "explicacao": "Código de Ética, Resolução Cofen 564/2017."}, {"id": 2000004508, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "Qual o dever do profissional de enfermagem quanto aos registros?", "verso": "Registrar no prontuário as informações inerentes à assistência, de forma clara, objetiva, cronológica, legível e completa, sem rasuras.", "explicacao": "Resolução Cofen 564/2017 e 514/2016 (guia de registros)."}, {"id": 2000004509, "trilha": "saude", "materia": "enf", "assunto": "Ética", "tipo": "pergunta", "frente": "O profissional pode executar prescrição com erro evidente?", "verso": "Não. Deve recusar-se a executar prescrições com erro ou ilegíveis, comunicando o prescritor.", "explicacao": "Código de Ética dos Profissionais de Enfermagem."}, {"id": 2000004510, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "O que são os sons de Korotkoff?", "verso": "Sons ouvidos com o estetoscópio durante a medida da pressão arterial: o primeiro marca a pressão sistólica e o desaparecimento marca a diastólica.", "explicacao": "Método auscultatório."}, {"id": 2000004511, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "O que acontece se o manguito for pequeno demais para o braço?", "verso": "A pressão arterial medida fica falsamente elevada.", "explicacao": "Manguito grande demais dá valor falsamente baixo."}, {"id": 2000004512, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "O que é hipotensão ortostática?", "verso": "Queda da pressão sistólica de pelo menos 20 mmHg ou da diastólica de pelo menos 10 mmHg em até 3 minutos após ficar em pé.", "explicacao": "Risco de quedas, comum em idosos."}, {"id": 2000004513, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Quais os principais locais de verificação do pulso?", "verso": "Radial, carotídeo, braquial, femoral, poplíteo, pedioso e apical.", "explicacao": "Na PCR do adulto, verifica-se o carotídeo."}, {"id": 2000004514, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "O que é déficit de pulso?", "verso": "Diferença entre o pulso apical (coração) e o radial, verificados ao mesmo tempo.", "explicacao": "Comum na fibrilação atrial."}, {"id": 2000004515, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "O que é a respiração de Cheyne-Stokes?", "verso": "Ciclos de respiração que aumentam e diminuem de profundidade, intercalados com períodos de apneia.", "explicacao": "Comum na insuficiência cardíaca grave e em lesões neurológicas."}, {"id": 2000004516, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "O que é a respiração de Kussmaul?", "verso": "Respiração profunda e rápida, típica da acidose metabólica, como na cetoacidose diabética.", "explicacao": "Tentativa de eliminar CO₂."}, {"id": 2000004517, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "pergunta", "frente": "Qual a escala mais usada para medir a dor em adultos?", "verso": "A escala visual analógica ou numérica de 0 a 10.", "explicacao": "Em crianças, a escala de faces; em pacientes não verbais, escalas comportamentais."}, {"id": 2000004518, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pergunta", "frente": "Qual a ordem do exame físico do abdome?", "verso": "Inspeção, ausculta, percussão e palpação.", "explicacao": "A ausculta vem antes para não alterar os ruídos hidroaéreos."}, {"id": 2000004519, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pares", "frente": "O que são sibilos, roncos e estertores crepitantes na ausculta?", "verso": "Sibilos: sons agudos por estreitamento das vias aéreas (asma). Roncos: sons graves por secreção em vias maiores. Estertores crepitantes: estalidos finos nos alvéolos (pneumonia, congestão).", "explicacao": "Ruídos adventícios."}, {"id": 2000004520, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pares", "frente": "Qual a diferença entre miose, midríase e anisocoria?", "verso": "Miose: pupila contraída. Midríase: pupila dilatada. Anisocoria: pupilas de tamanhos diferentes.", "explicacao": "Anisocoria nova pode indicar lesão neurológica grave."}, {"id": 2000004521, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pergunta", "frente": "O que é turgor da pele e o que indica quando diminuído?", "verso": "Elasticidade da pele ao ser pinçada; diminuído indica desidratação.", "explicacao": "A prega cutânea demora a voltar."}, {"id": 2000004522, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pergunta", "frente": "O que é o tempo de enchimento capilar e qual o normal?", "verso": "Tempo para a cor voltar ao leito ungueal após pressioná-lo; normal até 2 segundos (até 3 s em algumas referências).", "explicacao": "Aumentado sugere má perfusão."}, {"id": 2000004523, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pares", "frente": "Qual a diferença entre dispneia, ortopneia e dispneia paroxística noturna?", "verso": "Dispneia: falta de ar. Ortopneia: falta de ar ao deitar, que melhora sentado. DPN: acorda à noite com falta de ar.", "explicacao": "Ortopneia e DPN são típicas da insuficiência cardíaca."}, {"id": 2000004524, "trilha": "saude", "materia": "enf", "assunto": "Exame físico", "tipo": "pares", "frente": "Qual a diferença entre taquicardia, bradicardia e arritmia?", "verso": "Taquicardia: FC acima de 100 bpm no adulto. Bradicardia: abaixo de 60 bpm. Arritmia: ritmo irregular.", "explicacao": "Avaliar sempre com o estado clínico."}, {"id": 2000004525, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Quantos miligramas há em 1 grama? E quantos microgramas em 1 miligrama?", "verso": "1 g = 1.000 mg; 1 mg = 1.000 mcg.", "explicacao": "Conversão básica para cálculo de doses."}, {"id": 2000004526, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição: 750 mg de cefalotina. Frasco de 1 g diluído em 10 mL. Quanto aspirar?", "verso": "7,5 mL.", "explicacao": "1.000 mg ─ 10 mL; 750 mg ─ x. x = 7,5 mL."}, {"id": 2000004527, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição: 2.500 UI de heparina. Frasco com 5.000 UI/mL. Quanto aspirar?", "verso": "0,5 mL.", "explicacao": "2.500 ÷ 5.000."}, {"id": 2000004528, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição: 40 mg de furosemida. Ampola de 20 mg em 2 mL. Quanto aspirar?", "verso": "4 mL (2 ampolas).", "explicacao": "20 mg ─ 2 mL; 40 mg ─ 4 mL."}, {"id": 2000004529, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição: 0,5 mg de digoxina. Comprimidos de 0,25 mg. Quantos comprimidos?", "verso": "2 comprimidos.", "explicacao": "0,5 ÷ 0,25."}, {"id": 2000004530, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Quantos mEq de potássio há em 10 mL de KCl a 19,1%?", "verso": "Cerca de 25 mEq.", "explicacao": "Cada mL de KCl 19,1% tem cerca de 2,5 mEq de potássio."}, {"id": 2000004531, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Quantas gotas por minuto para infundir 1.500 mL em 12 horas?", "verso": "Cerca de 42 gotas/min.", "explicacao": "1.500 ÷ (12 × 3) = 41,7."}, {"id": 2000004532, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Quantas microgotas por minuto para 250 mL em 5 horas?", "verso": "50 microgotas/min.", "explicacao": "Microgotas = volume ÷ horas."}, {"id": 2000004533, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Um soro de 500 mL deve correr a 21 gotas/min. Em quanto tempo termina?", "verso": "Cerca de 8 horas.", "explicacao": "Tempo = 500 ÷ (21 × 3) ≈ 7,9 h."}, {"id": 2000004534, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Quanto de glicose há em 250 mL de SG 10%?", "verso": "25 g.", "explicacao": "10 g em 100 mL."}, {"id": 2000004535, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição: 1 g de dipirona IV. Ampola de 500 mg/mL em 2 mL. Quanto aspirar?", "verso": "2 mL.", "explicacao": "500 mg ─ 1 mL; 1.000 mg ─ 2 mL."}, {"id": 2000004536, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Uma criança de 15 kg tem prescrição de 20 mg/kg/dia de um antibiótico dividido de 8/8 h. Qual a dose por horário?", "verso": "100 mg.", "explicacao": "20 × 15 = 300 mg/dia; 300 ÷ 3 doses."}, {"id": 2000004537, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Por que não se aspira (puxa o êmbolo) ao aplicar heparina subcutânea?", "verso": "Para evitar hematomas no local.", "explicacao": "Também não se massageia após a aplicação."}, {"id": 2000004538, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Quais os locais para aplicação de insulina subcutânea?", "verso": "Abdome (afastado do umbigo), face posterior dos braços, face anterior e lateral das coxas e região superior dos glúteos.", "explicacao": "Fazer rodízio para evitar lipodistrofia."}, {"id": 2000004539, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Por que a via sublingual tem ação rápida?", "verso": "Porque o medicamento é absorvido direto pelos vasos sob a língua e não passa pelo fígado na primeira passagem.", "explicacao": "Ex.: nitrato no angina."}, {"id": 2000004540, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "O que fazer antes de administrar medicamento por sonda nasoenteral?", "verso": "Confirmar o posicionamento, pausar a dieta se indicado, triturar comprimidos que podem ser triturados, diluir e lavar a sonda com água antes e depois.", "explicacao": "Não triturar comprimidos de liberação prolongada ou com revestimento entérico."}, {"id": 2000004541, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Por que não se deve misturar medicamentos na mesma seringa sem conhecer a compatibilidade?", "verso": "Pelo risco de precipitação e perda do efeito ou reação adversa.", "explicacao": "Verificar a compatibilidade em tabela ou com o farmacêutico."}, {"id": 2000004542, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Qual o cuidado ao administrar medicamento por via retal (supositório)?", "verso": "Paciente em posição de Sims (lateral esquerda), introduzir o supositório além do esfíncter anal interno.", "explicacao": "Pedir que o paciente retenha por alguns minutos."}, {"id": 2000004543, "trilha": "saude", "materia": "enf", "assunto": "Oxigenoterapia", "tipo": "pergunta", "frente": "Qual dispositivo fornece a maior concentração de oxigênio sem ventilação mecânica?", "verso": "A máscara não reinalante com reservatório.", "explicacao": "Pode oferecer FiO₂ próxima de 90% a 100% com fluxo alto."}, {"id": 2000004544, "trilha": "saude", "materia": "enf", "assunto": "Oxigenoterapia", "tipo": "pergunta", "frente": "Por que o oxigênio deve ser dado com cautela em pacientes com DPOC retentores de CO₂?", "verso": "Porque oxigênio em alto fluxo pode reduzir o estímulo respiratório e agravar a hipercapnia. Usa-se a menor dose para saturação alvo de 88% a 92%.", "explicacao": "Máscara de Venturi é útil."}, {"id": 2000004545, "trilha": "saude", "materia": "enf", "assunto": "Oxigenoterapia", "tipo": "pergunta", "frente": "Por que se umidifica o oxigênio em fluxos maiores?", "verso": "Para evitar o ressecamento das mucosas.", "explicacao": "Usar água destilada estéril no umidificador."}, {"id": 2000004546, "trilha": "saude", "materia": "enf", "assunto": "Vias aéreas", "tipo": "pergunta", "frente": "Quais os cuidados com a traqueostomia?", "verso": "Aspirar secreções com técnica estéril, limpar a cânula interna, trocar o curativo e o cadarço, manter a umidificação e o cuff na pressão adequada.", "explicacao": "Ter cânula reserva à beira do leito."}, {"id": 2000004547, "trilha": "saude", "materia": "enf", "assunto": "Vias aéreas", "tipo": "pergunta", "frente": "Qual o tempo máximo de cada aspiração de vias aéreas?", "verso": "Até 10 a 15 segundos por vez.", "explicacao": "Hiperoxigenar antes e depois, se indicado."}, {"id": 2000004548, "trilha": "saude", "materia": "enf", "assunto": "Drenagem torácica", "tipo": "pergunta", "frente": "Onde deve ficar o frasco do dreno de tórax em selo d'água?", "verso": "Sempre abaixo do nível do tórax, para evitar refluxo.", "explicacao": "Observar oscilação da coluna líquida e borbulhamento."}, {"id": 2000004549, "trilha": "saude", "materia": "enf", "assunto": "Drenagem torácica", "tipo": "pergunta", "frente": "O dreno de tórax deve ser clampeado no transporte do paciente?", "verso": "Em regra não, pois pode causar pneumotórax hipertensivo. Mantém-se o frasco abaixo do tórax.", "explicacao": "Clampear só por curto período e com indicação."}, {"id": 2000004550, "trilha": "saude", "materia": "enf", "assunto": "Drenagem torácica", "tipo": "pergunta", "frente": "O que indica a oscilação da coluna de líquido no dreno de tórax?", "verso": "Que o sistema está pérvio e acompanha a respiração.", "explicacao": "A ausência pode indicar obstrução ou reexpansão completa do pulmão."}, {"id": 2000004551, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Quais as fases da cicatrização?", "verso": "Inflamatória, proliferativa (granulação) e de maturação (remodelação).", "explicacao": "A maturação pode durar meses."}, {"id": 2000004552, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pares", "frente": "Qual a diferença entre cicatrização por segunda e por terceira intenção?", "verso": "Segunda: a ferida fica aberta e fecha por granulação, de dentro para fora. Terceira: a ferida é deixada aberta por um tempo (ex.: infecção) e depois fechada.", "explicacao": "Primeira intenção: bordas aproximadas por sutura."}, {"id": 2000004553, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Quais os tipos de desbridamento?", "verso": "Autolítico, enzimático, mecânico, cirúrgico (instrumental) e biológico (larvas).", "explicacao": "O autolítico usa a umidade da própria ferida (hidrogel, hidrocoloide)."}, {"id": 2000004554, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Para que serve o hidrogel?", "verso": "Manter o meio úmido e promover desbridamento autolítico de tecidos desvitalizados.", "explicacao": "Indicado para feridas secas ou com necrose."}, {"id": 2000004555, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Para que serve o curativo de carvão ativado com prata?", "verso": "Controlar odor e exsudato e reduzir a carga bacteriana em feridas infectadas.", "explicacao": "Não deve ser cortado em alguns produtos."}, {"id": 2000004556, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Para que servem as espumas (poliuretano) em feridas?", "verso": "Absorver exsudato moderado a intenso e proteger a ferida.", "explicacao": "Também usadas na prevenção de lesão por pressão."}, {"id": 2000004557, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pares", "frente": "Quais as diferenças entre úlcera venosa e arterial?", "verso": "Venosa: no terço distal da perna, perto do maléolo medial, rasa, com edema e exsudato. Arterial: em pés e dedos, profunda, pálida, dolorosa, com pulsos diminuídos.", "explicacao": "A terapia compressiva serve para a venosa e é contraindicada na arterial grave."}, {"id": 2000004558, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "O que é deiscência e o que é evisceração?", "verso": "Deiscência: abertura das bordas da ferida operatória. Evisceração: saída de vísceras pela ferida aberta.", "explicacao": "Na evisceração, cobrir com compressa estéril úmida com soro e chamar o médico."}, {"id": 2000004559, "trilha": "saude", "materia": "enf", "assunto": "Ostomias", "tipo": "pares", "frente": "Qual a diferença entre o efluente da colostomia e o da ileostomia?", "verso": "Colostomia: fezes mais formadas, conforme a porção do cólon. Ileostomia: efluente líquido e irritante para a pele.", "explicacao": "A ileostomia exige mais cuidado com a pele."}, {"id": 2000004560, "trilha": "saude", "materia": "enf", "assunto": "Ostomias", "tipo": "pergunta", "frente": "Qual a cor e o aspecto normal do estoma?", "verso": "Vermelho vivo ou rosado, úmido e brilhante.", "explicacao": "Estoma escuro ou arroxeado indica isquemia."}, {"id": 2000004561, "trilha": "saude", "materia": "enf", "assunto": "Ostomias", "tipo": "pergunta", "frente": "Qual o tamanho correto do recorte da bolsa de ostomia?", "verso": "Do tamanho do estoma, com folga de cerca de 2 a 3 mm.", "explicacao": "Recorte grande expõe a pele ao efluente."}, {"id": 2000004562, "trilha": "saude", "materia": "enf", "assunto": "Nutrição", "tipo": "pergunta", "frente": "Qual a posição do paciente durante a dieta enteral?", "verso": "Cabeceira elevada entre 30° e 45°, mantida até cerca de 30 a 60 minutos após a dieta.", "explicacao": "Previne broncoaspiração."}, {"id": 2000004563, "trilha": "saude", "materia": "enf", "assunto": "Nutrição", "tipo": "pergunta", "frente": "Para que se lava a sonda enteral com água?", "verso": "Para evitar obstrução, antes e após a dieta e os medicamentos.", "explicacao": "Em geral, 20 a 30 mL em adultos."}, {"id": 2000004564, "trilha": "saude", "materia": "enf", "assunto": "Nutrição", "tipo": "pergunta", "frente": "Por qual via, em regra, se administra a nutrição parenteral total?", "verso": "Por acesso venoso central, por ser solução hiperosmolar.", "explicacao": "Controlar glicemia e não interromper bruscamente."}, {"id": 2000004565, "trilha": "saude", "materia": "enf", "assunto": "Nutrição", "tipo": "pergunta", "frente": "Qual o principal risco metabólico da nutrição parenteral?", "verso": "A hiperglicemia, além de distúrbios eletrolíticos e infecção do cateter.", "explicacao": "Monitorar a glicemia capilar."}, {"id": 2000004566, "trilha": "saude", "materia": "enf", "assunto": "Eliminação", "tipo": "pergunta", "frente": "Qual o volume de diurese considerado oligúria e anúria no adulto?", "verso": "Oligúria: menos de 400 mL em 24 h (ou menos de 0,5 mL/kg/h). Anúria: menos de 100 mL em 24 h.", "explicacao": "Sinais de lesão renal ou hipovolemia."}, {"id": 2000004567, "trilha": "saude", "materia": "enf", "assunto": "Eliminação", "tipo": "pergunta", "frente": "Qual a diurese mínima esperada no adulto por hora?", "verso": "Cerca de 0,5 mL/kg/h.", "explicacao": "Ex.: 70 kg → 35 mL/h."}, {"id": 2000004568, "trilha": "saude", "materia": "enf", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "Que cuidados se tem com o braço da fístula arteriovenosa para hemodiálise?", "verso": "Não verificar pressão, não puncionar, não fazer garrote nem carregar peso; observar o frêmito (vibração) diariamente.", "explicacao": "O frêmito indica fístula funcionando."}, {"id": 2000004569, "trilha": "saude", "materia": "enf", "assunto": "Nefrologia", "tipo": "pares", "frente": "Qual a diferença entre hemodiálise e diálise peritoneal?", "verso": "Hemodiálise: o sangue é filtrado por uma máquina. Diálise peritoneal: o próprio peritônio funciona como filtro, com líquido infundido no abdome.", "explicacao": "A peritoneal pode ser feita em casa."}, {"id": 2000004570, "trilha": "saude", "materia": "enf", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a tríade de Cushing?", "verso": "Hipertensão arterial, bradicardia e alteração do padrão respiratório, sinal de hipertensão intracraniana grave.", "explicacao": "Indica risco de herniação cerebral."}, {"id": 2000004571, "trilha": "saude", "materia": "enf", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os cuidados durante uma crise convulsiva?", "verso": "Proteger a cabeça, afastar objetos, lateralizar o paciente, não colocar nada na boca, observar e cronometrar a crise.", "explicacao": "Não conter os movimentos."}, {"id": 2000004572, "trilha": "saude", "materia": "enf", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Qual a posição da cabeceira no paciente com hipertensão intracraniana?", "verso": "Cabeceira a 30°, com a cabeça alinhada ao corpo (posição neutra).", "explicacao": "Facilita o retorno venoso cerebral."}, {"id": 2000004573, "trilha": "saude", "materia": "enf", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Onde se posiciona o eletrodo V1 no eletrocardiograma?", "verso": "No 4º espaço intercostal, à direita do esterno.", "explicacao": "V2: 4º espaço à esquerda do esterno."}, {"id": 2000004574, "trilha": "saude", "materia": "enf", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Onde se posiciona o eletrodo V4?", "verso": "No 5º espaço intercostal, na linha hemiclavicular esquerda.", "explicacao": "V6: 5º espaço, na linha axilar média."}, {"id": 2000004575, "trilha": "saude", "materia": "enf", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "O que representa cada onda do ECG?", "verso": "P: despolarização atrial. QRS: despolarização ventricular. T: repolarização ventricular.", "explicacao": "O segmento ST é avaliado no infarto."}, {"id": 2000004576, "trilha": "saude", "materia": "enf", "assunto": "Cardiologia", "tipo": "pares", "frente": "Qual a diferença entre desfibrilação e cardioversão elétrica?", "verso": "Desfibrilação: choque não sincronizado, na PCR em fibrilação ventricular ou taquicardia ventricular sem pulso. Cardioversão: choque sincronizado com o QRS, em arritmias com pulso.", "explicacao": "Na cardioversão, o paciente costuma ser sedado."}, {"id": 2000004577, "trilha": "saude", "materia": "enf", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Que cuidados se tem com o paciente com insuficiência cardíaca?", "verso": "Pesar diariamente, controlar líquidos e sal, observar edema e dispneia, manter cabeceira elevada e controlar diurese.", "explicacao": "Ganho rápido de peso sugere retenção de líquido."}, {"id": 2000004578, "trilha": "saude", "materia": "enf", "assunto": "Choque", "tipo": "pergunta", "frente": "Quais os tipos de choque?", "verso": "Hipovolêmico, cardiogênico, distributivo (séptico, anafilático, neurogênico) e obstrutivo (tamponamento, embolia, pneumotórax hipertensivo).", "explicacao": "Classificação pela causa."}, {"id": 2000004579, "trilha": "saude", "materia": "enf", "assunto": "Choque", "tipo": "pergunta", "frente": "Qual sinal diferencia o choque neurogênico dos demais?", "verso": "Hipotensão com bradicardia e pele quente, por perda do tônus simpático após lesão medular.", "explicacao": "Nos outros choques, em geral há taquicardia."}, {"id": 2000004580, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Como se controla uma hemorragia externa grave em membro?", "verso": "Compressão direta e, se não for suficiente, torniquete acima da lesão, anotando o horário.", "explicacao": "Prioridade X no atendimento ao trauma."}, {"id": 2000004581, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Quais as cores do Protocolo de Manchester e o tempo-alvo de cada uma?", "verso": "Vermelho: imediato. Laranja: 10 min. Amarelo: 60 min. Verde: 120 min. Azul: 240 min.", "explicacao": "Classificação de risco na emergência."}, {"id": 2000004582, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a conduta inicial na intoxicação exógena?", "verso": "Garantir vias aéreas, respiração e circulação, identificar o agente, contatar o centro de informação toxicológica (CIATox) e seguir as medidas específicas.", "explicacao": "Não provocar vômito de rotina."}, {"id": 2000004583, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a conduta em queimaduras térmicas no primeiro atendimento?", "verso": "Interromper a queimadura, resfriar com água corrente em temperatura ambiente, retirar anéis e roupas não aderidas e cobrir com material limpo.", "explicacao": "Não usar gelo, pasta de dente ou manteiga."}, {"id": 2000004584, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "Quais os tempos cirúrgicos fundamentais?", "verso": "Diérese (corte), hemostasia, exérese (cirurgia propriamente dita) e síntese (fechamento).", "explicacao": "Ordem clássica."}, {"id": 2000004585, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "Quais as funções do instrumentador cirúrgico?", "verso": "Preparar a mesa, prever e entregar os instrumentos à equipe, manter a ordem e a assepsia do material.", "explicacao": "Faz a contagem de compressas e instrumentais com o circulante."}, {"id": 2000004586, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "O que é a posição de litotomia?", "verso": "Decúbito dorsal com as pernas elevadas e afastadas em perneiras, usada em cirurgias ginecológicas, urológicas e partos.", "explicacao": "Risco de lesão nervosa e circulatória nas pernas."}, {"id": 2000004587, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "Para que serve a placa do bisturi elétrico?", "verso": "Fechar o circuito da corrente (eletrodo de retorno), evitando queimaduras.", "explicacao": "Colocar em área muscular, seca e sem pelos, próxima ao campo operatório."}, {"id": 2000004588, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "Quais complicações comuns do pós-operatório imediato?", "verso": "Dor, náuseas e vômitos, hipotermia, sangramento, hipotensão, retenção urinária e depressão respiratória.", "explicacao": "Monitorar na SRPA."}, {"id": 2000004589, "trilha": "saude", "materia": "enf", "assunto": "Centro cirúrgico", "tipo": "pergunta", "frente": "O que é a escala de Aldrete e Kroulik?", "verso": "Escala usada na recuperação pós-anestésica para avaliar atividade, respiração, circulação, consciência e saturação, orientando a alta da SRPA.", "explicacao": "Pontuação de 0 a 10; em geral, alta com 9 ou mais."}, {"id": 2000004590, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "Quais as etapas do processamento de produtos na CME?", "verso": "Recepção, limpeza, inspeção, preparo e acondicionamento, esterilização, armazenamento e distribuição.", "explicacao": "RDC 15/2012 da Anvisa."}, {"id": 2000004591, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "Para que serve o teste de Bowie-Dick?", "verso": "Avaliar a remoção do ar e a penetração do vapor em autoclaves com pré-vácuo, feito diariamente antes da primeira carga.", "explicacao": "Teste de desempenho do equipamento."}, {"id": 2000004592, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "Qual a diferença entre indicadores químicos e biológicos?", "verso": "Químicos: mudam de cor ao serem expostos a parâmetros do processo. Biológicos: usam esporos de microrganismos resistentes e comprovam a esterilização.", "explicacao": "O biológico é o mais confiável."}, {"id": 2000004593, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "O que significa validade da esterilização relacionada a eventos?", "verso": "O material continua estéril enquanto a embalagem estiver íntegra, seca e armazenada corretamente, e não por prazo fixo.", "explicacao": "Eventos como queda, umidade ou rasgo invalidam."}, {"id": 2000004594, "trilha": "saude", "materia": "enf", "assunto": "CME", "tipo": "pergunta", "frente": "Qual a etapa mais importante do processamento de artigos?", "verso": "A limpeza, pois a sujeira impede a ação da desinfecção e da esterilização.", "explicacao": "Sem limpeza adequada não há esterilização."}, {"id": 2000004595, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual a ordem recomendada de colocação dos EPIs?", "verso": "Avental, máscara (ou respirador), óculos ou protetor facial e luvas.", "explicacao": "Antes, higiene das mãos."}, {"id": 2000004596, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Qual a ordem recomendada de retirada dos EPIs?", "verso": "Luvas, avental, higiene das mãos, óculos ou protetor facial, máscara e nova higiene das mãos.", "explicacao": "Os itens mais contaminados saem primeiro."}, {"id": 2000004597, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "As luvas substituem a higiene das mãos?", "verso": "Não. Deve-se higienizar as mãos antes de calçar e após retirar as luvas.", "explicacao": "Luvas podem ter microfuros."}, {"id": 2000004598, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "O que são as precauções padrão?", "verso": "Medidas aplicadas a todos os pacientes, independentemente do diagnóstico: higiene das mãos, uso de EPI conforme o risco, descarte seguro de perfurocortantes e cuidados com ambiente e materiais.", "explicacao": "Base da prevenção de infecções."}, {"id": 2000004599, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Que precauções se usam para paciente com varicela?", "verso": "Precauções para aerossóis e de contato, em quarto privativo.", "explicacao": "Profissionais suscetíveis não devem atender."}, {"id": 2000004600, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Por que a higiene das mãos deve ser com água e sabão no caso de Clostridioides difficile?", "verso": "Porque o álcool não elimina os esporos dessa bactéria.", "explicacao": "Também se usam precauções de contato."}, {"id": 2000004601, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "pergunta", "frente": "Que precaução se usa para meningite meningocócica nas primeiras 24 horas de tratamento?", "verso": "Precaução para gotículas, com máscara cirúrgica.", "explicacao": "Após 24 h de antibiótico eficaz, pode ser suspensa."}, {"id": 2000004602, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Quais vacinas do calendário são de vírus ou bactérias vivos atenuados?", "verso": "BCG, tríplice viral, varicela, febre amarela, rotavírus, entre outras.", "explicacao": "Em regra contraindicadas a gestantes e imunodeprimidos graves."}, {"id": 2000004603, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Qual o intervalo entre duas vacinas vivas injetáveis não aplicadas no mesmo dia?", "verso": "30 dias.", "explicacao": "Podem ser aplicadas no mesmo dia, com exceções definidas pelo Ministério da Saúde."}, {"id": 2000004604, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Qual a evolução esperada da lesão da BCG?", "verso": "Mácula, pápula, pústula, úlcera e crosta, formando cicatriz em cerca de 6 a 12 semanas.", "explicacao": "Não se deve cobrir nem colocar medicamento."}, {"id": 2000004605, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "Qual a contraindicação geral comum a todas as vacinas?", "verso": "Reação anafilática prévia à vacina ou a algum de seus componentes.", "explicacao": "Doença febril aguda moderada ou grave é motivo de adiamento."}, {"id": 2000004606, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "pergunta", "frente": "O que fazer com o frasco de vacina exposto a temperatura fora da faixa recomendada?", "verso": "Suspender o uso, manter refrigerado e identificado e comunicar a coordenação de imunizações para avaliação.", "explicacao": "Não descartar nem usar sem orientação."}, {"id": 2000004607, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual a periodicidade do exame citopatológico do colo do útero no Brasil?", "verso": "Mulheres de 25 a 64 anos que já tiveram atividade sexual: a cada 3 anos, após dois exames anuais seguidos normais.", "explicacao": "Diretrizes do INCA."}, {"id": 2000004608, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual a faixa etária e a periodicidade da mamografia de rastreamento recomendada pelo Ministério da Saúde?", "verso": "Mulheres de 50 a 69 anos, a cada 2 anos.", "explicacao": "Diretrizes do INCA para o rastreamento organizado."}, {"id": 2000004609, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Quais os sinais de certeza da gravidez?", "verso": "Batimentos cardíacos fetais, movimentos fetais percebidos pelo examinador e visualização do embrião ou feto na ultrassonografia.", "explicacao": "Atraso menstrual e náuseas são sinais de presunção."}, {"id": 2000004610, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Qual a frequência cardíaca fetal normal?", "verso": "Entre 110 e 160 batimentos por minuto.", "explicacao": "Avaliada com sonar Doppler ou estetoscópio de Pinard."}, {"id": 2000004611, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Para que servem as manobras de Leopold?", "verso": "Para identificar a situação, a apresentação e a posição do feto pela palpação abdominal.", "explicacao": "São quatro tempos."}, {"id": 2000004612, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Quais as fases do puerpério?", "verso": "Imediato (1º ao 10º dia), tardio (11º ao 42º dia) e remoto (após o 42º dia).", "explicacao": "Consulta puerperal até 42 dias."}, {"id": 2000004613, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Quais os \"4 Ts\" das causas de hemorragia pós-parto?", "verso": "Tônus (atonia uterina), Trauma (lacerações), Tecido (restos placentários) e Trombina (distúrbios de coagulação).", "explicacao": "A atonia é a principal causa."}, {"id": 2000004614, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Qual medicamento é usado de rotina para prevenir a hemorragia pós-parto?", "verso": "Ocitocina, 10 UI intramuscular logo após o nascimento.", "explicacao": "Parte do manejo ativo do 3º período."}, {"id": 2000004615, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Em que situações o aleitamento materno é contraindicado no Brasil?", "verso": "Mãe com HIV ou HTLV, e uso de certos medicamentos incompatíveis.", "explicacao": "Nesses casos, o SUS fornece fórmula infantil."}, {"id": 2000004616, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "O que é o alojamento conjunto?", "verso": "Sistema em que o recém-nascido sadio fica ao lado da mãe 24 horas por dia, até a alta.", "explicacao": "Favorece o vínculo e a amamentação."}, {"id": 2000004617, "trilha": "saude", "materia": "enf", "assunto": "Neonatologia", "tipo": "pergunta", "frente": "Por que se aplica vitamina K no recém-nascido?", "verso": "Para prevenir a doença hemorrágica do recém-nascido.", "explicacao": "Dose IM logo após o nascimento."}, {"id": 2000004618, "trilha": "saude", "materia": "enf", "assunto": "Neonatologia", "tipo": "pergunta", "frente": "Como se faz o cuidado do coto umbilical?", "verso": "Mantê-lo limpo e seco, com álcool 70% a cada troca de fralda, sem cobri-lo.", "explicacao": "Cai, em geral, entre 7 e 15 dias."}, {"id": 2000004619, "trilha": "saude", "materia": "enf", "assunto": "Neonatologia", "tipo": "pergunta", "frente": "Qual a perda de peso fisiológica esperada nos primeiros dias de vida?", "verso": "Até cerca de 10% do peso ao nascer, recuperado em 10 a 15 dias.", "explicacao": "Perdas maiores exigem avaliação."}, {"id": 2000004620, "trilha": "saude", "materia": "enf", "assunto": "Neonatologia", "tipo": "pergunta", "frente": "Quando se fecham as fontanelas posterior e anterior?", "verso": "Posterior: por volta de 2 meses. Anterior (bregmática): entre 12 e 18 meses.", "explicacao": "Fontanela abaulada pode indicar hipertensão intracraniana; deprimida, desidratação."}, {"id": 2000004621, "trilha": "saude", "materia": "enf", "assunto": "Neonatologia", "tipo": "pergunta", "frente": "Qual a temperatura axilar normal do recém-nascido?", "verso": "Entre 36,5 °C e 37,5 °C.", "explicacao": "O RN perde calor facilmente: contato pele a pele ajuda."}, {"id": 2000004622, "trilha": "saude", "materia": "enf", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os sinais de desidratação na criança?", "verso": "Sede, olhos fundos, boca seca, choro sem lágrimas, sinal da prega lento, irritabilidade ou letargia.", "explicacao": "Avaliação do plano de hidratação."}, {"id": 2000004623, "trilha": "saude", "materia": "enf", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Qual o principal cuidado ao administrar medicamento líquido via oral em criança?", "verso": "Usar seringa dosadora ou copo graduado, nunca colher caseira.", "explicacao": "Evita erro de dose."}, {"id": 2000004624, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os tipos de CAPS?", "verso": "CAPS I, II e III (por porte e funcionamento 24 h no III), CAPSi (infantojuvenil) e CAPS AD (álcool e outras drogas), incluindo o CAPS AD III.", "explicacao": "Portaria de consolidação da RAPS."}, {"id": 2000004625, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Como abordar a pessoa com risco de suicídio?", "verso": "Perguntar diretamente sobre ideação, ouvir sem julgar, não deixar a pessoa sozinha em risco alto, retirar meios letais e encaminhar ao serviço de saúde mental.", "explicacao": "Perguntar não induz o suicídio."}, {"id": 2000004626, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pares", "frente": "Qual a diferença entre delirium e demência?", "verso": "Delirium: início agudo, flutuante, com alteração da atenção, geralmente reversível. Demência: início insidioso, progressivo, com perda de memória e de outras funções.", "explicacao": "O delirium é emergência médica."}, {"id": 2000004627, "trilha": "saude", "materia": "enf", "assunto": "Saúde do idoso", "tipo": "pergunta", "frente": "Quais medidas previnem quedas no ambiente hospitalar?", "verso": "Grades elevadas quando indicado, cama baixa e travada, campainha ao alcance, iluminação, piso seco, calçado adequado e revisão de medicamentos.", "explicacao": "Avaliar risco com escalas como a de Morse."}, {"id": 2000004628, "trilha": "saude", "materia": "enf", "assunto": "Doenças crônicas", "tipo": "pergunta", "frente": "Que orientações dar ao paciente com hipertensão?", "verso": "Reduzir sal, manter peso adequado, praticar atividade física, evitar álcool e tabaco e tomar os medicamentos regularmente, mesmo sem sintomas.", "explicacao": "Mudança no estilo de vida."}, {"id": 2000004629, "trilha": "saude", "materia": "enf", "assunto": "Doenças crônicas", "tipo": "pergunta", "frente": "Quais os sinais de hipoglicemia?", "verso": "Sudorese, tremores, palpitação, fome, confusão mental e, nos casos graves, convulsão e coma.", "explicacao": "Glicemia abaixo de 70 mg/dL."}, {"id": 2000004630, "trilha": "saude", "materia": "enf", "assunto": "Doenças infecciosas", "tipo": "pergunta", "frente": "Qual a duração mínima do tratamento da tuberculose pulmonar sensível?", "verso": "6 meses: 2 meses de fase intensiva (RIPE) e 4 meses de manutenção (RI).", "explicacao": "Tratamento diretamente observado é recomendado."}, {"id": 2000004631, "trilha": "saude", "materia": "enf", "assunto": "Doenças infecciosas", "tipo": "pergunta", "frente": "Qual efeito da rifampicina deve ser explicado ao paciente?", "verso": "A urina, o suor e as lágrimas podem ficar alaranjados.", "explicacao": "Efeito esperado, não é motivo para parar o tratamento."}, {"id": 2000004632, "trilha": "saude", "materia": "enf", "assunto": "Hemoterapia", "tipo": "pergunta", "frente": "Quais sinais indicam reação transfusional?", "verso": "Febre, calafrios, urticária, dispneia, dor lombar, hipotensão e hemoglobinúria.", "explicacao": "Parar a transfusão, manter acesso com soro fisiológico e comunicar."}, {"id": 2000004633, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "Quais os protocolos básicos de segurança do paciente do Ministério da Saúde?", "verso": "Identificação do paciente, prevenção de lesão por pressão, segurança na prescrição e administração de medicamentos, cirurgia segura, higiene das mãos e prevenção de quedas.", "explicacao": "Programa Nacional de Segurança do Paciente (Portaria 529/2013)."}, {"id": 2000004634, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "O que é o Núcleo de Segurança do Paciente?", "verso": "Instância do serviço de saúde que promove ações de segurança, notifica eventos adversos e monitora indicadores.", "explicacao": "RDC 36/2013 da Anvisa."}, {"id": 2000004635, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "O que é near miss (quase erro)?", "verso": "Incidente que não atingiu o paciente.", "explicacao": "Também deve ser notificado para prevenção."}, {"id": 2000004636, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "pergunta", "frente": "O que é a cultura justa em segurança do paciente?", "verso": "Ambiente em que os erros são tratados como falhas do sistema, sem punição automática, mas com responsabilização por condutas imprudentes.", "explicacao": "Incentiva notificar."}, {"id": 2000004637, "trilha": "saude", "materia": "enf", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é a escala de Fugulin?", "verso": "Sistema de classificação de pacientes pelo grau de dependência da enfermagem: cuidados mínimos, intermediários, alta dependência, semi-intensivos e intensivos.", "explicacao": "Base para o dimensionamento."}, {"id": 2000004638, "trilha": "saude", "materia": "enf", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que são indicadores de qualidade da assistência de enfermagem?", "verso": "Medidas como taxas de lesão por pressão, quedas, erros de medicação e infecção, usadas para monitorar e melhorar o cuidado.", "explicacao": "Gestão da qualidade."}, {"id": 2000004639, "trilha": "saude", "materia": "enf", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é o ciclo PDCA?", "verso": "Método de melhoria contínua: planejar (Plan), executar (Do), verificar (Check) e agir (Act).", "explicacao": "Usado na gestão da qualidade."}, {"id": 2000004640, "trilha": "saude", "materia": "enf", "assunto": "Teorias", "tipo": "pergunta", "frente": "Qual a teoria de enfermagem de Hildegard Peplau?", "verso": "Teoria das relações interpessoais: o cuidado se dá pela relação enfermeiro-paciente, com fases de orientação, identificação, exploração e resolução.", "explicacao": "Muito aplicada em saúde mental."}, {"id": 2000004641, "trilha": "saude", "materia": "enf", "assunto": "Teorias", "tipo": "pergunta", "frente": "Qual a teoria de Madeleine Leininger?", "verso": "Teoria da diversidade e universalidade do cuidado cultural (enfermagem transcultural).", "explicacao": "O cuidado deve respeitar a cultura do paciente."}, {"id": 2000004642, "trilha": "saude", "materia": "enf", "assunto": "Teorias", "tipo": "pergunta", "frente": "Qual a teoria de Callista Roy?", "verso": "Modelo de adaptação: a pessoa é um sistema que se adapta a estímulos em quatro modos (fisiológico, autoconceito, função de papel e interdependência).", "explicacao": "Teoria de enfermagem."}, {"id": 2000004643, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Qual a diferença entre epistaxe, otorragia e hematúria?", "verso": "Epistaxe: sangramento nasal. Otorragia: sangramento pelo ouvido. Hematúria: sangue na urina.", "explicacao": "Otorragia após trauma craniano sugere fratura de base de crânio."}, {"id": 2000004644, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Qual a diferença entre polaciúria, polidipsia e polifagia?", "verso": "Polaciúria: urinar muitas vezes, em pequeno volume. Polidipsia: sede excessiva. Polifagia: fome excessiva.", "explicacao": "Polidipsia, poliúria e polifagia são clássicas do diabetes."}, {"id": 2000004645, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Qual a diferença entre êmese, eructação e pirose?", "verso": "Êmese: vômito. Eructação: arroto. Pirose: azia (queimação retroesternal).", "explicacao": "Termos de sintomas digestivos."}, {"id": 2000004646, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Qual a diferença entre prurido, petéquias e equimoses?", "verso": "Prurido: coceira. Petéquias: pontos vermelhos pequenos de sangramento na pele. Equimoses: manchas roxas maiores.", "explicacao": "Petéquias podem indicar plaquetas baixas."}, {"id": 2000004647, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Qual a diferença entre lipotimia, síncope e vertigem?", "verso": "Lipotimia: sensação de desmaio sem perder a consciência. Síncope: perda transitória da consciência. Vertigem: sensação de que tudo gira.", "explicacao": "Termos neurológicos."}, {"id": 2000004648, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pergunta", "frente": "O que é colúria e acolia?", "verso": "Colúria: urina escura (cor de chá) por bilirrubina. Acolia: fezes claras (esbranquiçadas).", "explicacao": "Sinais de obstrução biliar ou hepatite."}, {"id": 2000004649, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pergunta", "frente": "O que é disfagia e odinofagia?", "verso": "Disfagia: dificuldade de engolir. Odinofagia: dor ao engolir.", "explicacao": "Risco de broncoaspiração na disfagia."}, {"id": 2000004650, "trilha": "saude", "materia": "enf", "assunto": "Coleta de exames", "tipo": "pergunta", "frente": "Quais os cuidados na coleta de hemocultura?", "verso": "Antissepsia rigorosa da pele, coleta antes do antibiótico, volume adequado e, em geral, dois pares de punções diferentes.", "explicacao": "Evitar coletar de cateter já instalado, salvo indicação."}, {"id": 2000004651, "trilha": "saude", "materia": "enf", "assunto": "Coleta de exames", "tipo": "pergunta", "frente": "Como se coleta a urina de 24 horas?", "verso": "Despreza-se a primeira urina da manhã, anota-se o horário e coleta-se toda a urina até a mesma hora do dia seguinte, incluindo essa última.", "explicacao": "Armazenar refrigerado se indicado."}, {"id": 2000004652, "trilha": "saude", "materia": "enf", "assunto": "Coleta de exames", "tipo": "pergunta", "frente": "Qual o cuidado na coleta de gasometria arterial?", "verso": "Fazer o teste de Allen antes da punção radial, retirar o ar da seringa heparinizada, comprimir o local por 5 minutos e enviar o material rapidamente.", "explicacao": "O teste de Allen avalia a circulação colateral da mão."}, {"id": 2000004653, "trilha": "saude", "materia": "enf", "assunto": "Terapia intravenosa", "tipo": "pergunta", "frente": "Qual a ordem de preferência das veias para punção periférica em adultos?", "verso": "Começar pelas veias mais distais dos membros superiores (dorso da mão e antebraço), evitando articulações e o membro com fístula ou esvaziamento ganglionar.", "explicacao": "Preservar a rede venosa."}, {"id": 2000004654, "trilha": "saude", "materia": "enf", "assunto": "Terapia intravenosa", "tipo": "pergunta", "frente": "Quais os sinais de infiltração do acesso venoso?", "verso": "Edema, pele fria e pálida, dor e diminuição ou parada do gotejamento.", "explicacao": "Retirar o cateter e elevar o membro."}, {"id": 2000004655, "trilha": "saude", "materia": "enf", "assunto": "Terapia intravenosa", "tipo": "pergunta", "frente": "O que é o PICC?", "verso": "Cateter central de inserção periférica, inserido em veia do braço até a veia cava, para terapias prolongadas.", "explicacao": "Enfermeiros capacitados podem inserir (Resolução Cofen 258/2001)."}, {"id": 2000004656, "trilha": "saude", "materia": "enf", "assunto": "Terapia intravenosa", "tipo": "pergunta", "frente": "Qual o ângulo de punção venosa periférica?", "verso": "Entre 15° e 30°, com o bisel voltado para cima.", "explicacao": "Depois, abaixar o cateter e avançá-lo."}, {"id": 2000004657, "trilha": "saude", "materia": "enf", "assunto": "Pele", "tipo": "pergunta", "frente": "O que é dermatite associada à incontinência?", "verso": "Inflamação da pele por contato prolongado com urina ou fezes.", "explicacao": "Prevenção: higiene suave, secagem e barreira protetora."}, {"id": 2000004658, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "O que é lesão por pressão tissular profunda?", "verso": "Área de pele íntegra ou não, com coloração vermelho-escura, marrom ou púrpura que não embranquece, ou bolha com sangue.", "explicacao": "Classificação NPIAP."}, {"id": 2000004659, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "O que é lesão por pressão não classificável?", "verso": "Perda total da pele em que a base está coberta por esfacelo ou escara, impedindo ver a profundidade.", "explicacao": "Só se classifica após o desbridamento."}, {"id": 2000004660, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "O que é lesão por pressão relacionada a dispositivo médico?", "verso": "Lesão causada pelo uso de dispositivos como sondas, máscaras, cateteres e talas, com o formato do dispositivo.", "explicacao": "Revisar a pele sob os dispositivos."}, {"id": 2000004661, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "Quais as regiões mais comuns de lesão por pressão?", "verso": "Sacral, calcâneos, trocânteres, ísquios, cotovelos, occipital e escápulas.", "explicacao": "Proeminências ósseas."}, {"id": 2000004662, "trilha": "saude", "materia": "enf", "assunto": "Lesão por pressão", "tipo": "pergunta", "frente": "Qual a pontuação da escala de Braden e o que indica um valor baixo?", "verso": "Vai de 6 a 23. Quanto menor a pontuação, maior o risco de lesão por pressão.", "explicacao": "Avalia seis domínios."}, {"id": 2000004663, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Qual o caráter das ações e serviços de saúde segundo a Constituição?", "verso": "São de relevância pública, cabendo ao Poder Público dispor sobre sua regulamentação, fiscalização e controle.", "explicacao": "CF, art. 197."}, {"id": 2000004664, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Como o SUS é financiado, segundo a Constituição?", "verso": "Com recursos do orçamento da seguridade social da União, dos estados, do DF e dos municípios, além de outras fontes.", "explicacao": "CF, art. 198, § 1º."}, {"id": 2000004665, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "A Constituição permite contratar agentes comunitários de saúde por processo seletivo público?", "verso": "Sim. Os gestores locais podem admitir ACS e agentes de combate às endemias por processo seletivo público.", "explicacao": "CF, art. 198, § 4º."}, {"id": 2000004666, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "pergunta", "frente": "Quais as competências do SUS ligadas ao trabalhador e ao meio ambiente no art. 200 da CF?", "verso": "Executar ações de saúde do trabalhador, colaborar na proteção do meio ambiente, incluindo o do trabalho, e participar da formulação da política de saneamento básico.", "explicacao": "CF, art. 200, II, IV e VIII."}, {"id": 2000004667, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Quais fatores a Lei 8.080 aponta como determinantes e condicionantes da saúde?", "verso": "Alimentação, moradia, saneamento básico, meio ambiente, trabalho, renda, educação, atividade física, transporte, lazer e acesso a bens e serviços essenciais.", "explicacao": "Lei 8.080/1990, art. 3º."}, {"id": 2000004668, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "A Lei 8.080 inclui a assistência farmacêutica no campo de atuação do SUS?", "verso": "Sim, a assistência terapêutica integral, inclusive farmacêutica.", "explicacao": "Lei 8.080/1990, art. 6º, I, d."}, {"id": 2000004669, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O que é a preservação da autonomia das pessoas como princípio do SUS?", "verso": "O respeito à integridade física e moral das pessoas e ao direito de decidir sobre o próprio tratamento.", "explicacao": "Lei 8.080/1990, art. 7º, III."}, {"id": 2000004670, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O direito à informação é princípio do SUS?", "verso": "Sim, às pessoas assistidas, sobre sua saúde.", "explicacao": "Lei 8.080/1990, art. 7º, V."}, {"id": 2000004671, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Quem exerce a direção do SUS no âmbito municipal?", "verso": "A Secretaria de Saúde ou órgão equivalente.", "explicacao": "Lei 8.080/1990, art. 9º, III. Na União, o Ministério da Saúde."}, {"id": 2000004672, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Os municípios podem formar consórcios para as ações de saúde?", "verso": "Sim, para desenvolver em conjunto as ações e os serviços que lhes correspondam.", "explicacao": "Lei 8.080/1990, art. 10."}, {"id": 2000004673, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Qual a competência da direção estadual do SUS em relação aos municípios?", "verso": "Promover a descentralização dos serviços para os municípios e prestar-lhes apoio técnico e financeiro, além de executar supletivamente ações e serviços.", "explicacao": "Lei 8.080/1990, art. 17."}, {"id": 2000004674, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "A Lei 8.080 prevê a participação complementar da iniciativa privada como?", "verso": "Quando as disponibilidades do SUS forem insuficientes para garantir a cobertura assistencial, por contrato ou convênio, com preferência às entidades filantrópicas e sem fins lucrativos.", "explicacao": "Lei 8.080/1990, arts. 24 e 25."}, {"id": 2000004675, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "Qual o direito da pessoa idosa ou com deficiência internada?", "verso": "Ter acompanhante, conforme as leis específicas.", "explicacao": "Estatuto da Pessoa Idosa e Lei Brasileira de Inclusão."}, {"id": 2000004676, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "pergunta", "frente": "O SUS deve garantir acompanhante à parturiente?", "verso": "Sim, um acompanhante de sua escolha durante o trabalho de parto, parto e pós-parto imediato.", "explicacao": "Lei 8.080/1990, art. 19-J (Lei 11.108/2005)."}, {"id": 2000004677, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Qual o caráter dos Conselhos de Saúde?", "verso": "Permanente e deliberativo, atuando na formulação de estratégias e no controle da execução da política de saúde, inclusive nos aspectos financeiros.", "explicacao": "Lei 8.142/1990, art. 1º, § 2º."}, {"id": 2000004678, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Qual a distribuição das vagas nos Conselhos de Saúde segundo a Resolução CNS 453/2012?", "verso": "50% de usuários, 25% de trabalhadores da saúde e 25% de gestores e prestadores de serviço.", "explicacao": "Paridade dos usuários com os demais segmentos."}, {"id": 2000004679, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "pergunta", "frente": "Para receber recursos do Fundo Nacional de Saúde, o que os municípios precisam ter?", "verso": "Fundo de Saúde, Conselho de Saúde paritário, plano de saúde, relatório de gestão, contrapartida de recursos no orçamento e plano de carreira, cargos e salários (prazo de implantação).", "explicacao": "Lei 8.142/1990, art. 4º."}, {"id": 2000004680, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que é a Rede de Atenção à Saúde no Decreto 7.508?", "verso": "Conjunto de ações e serviços de saúde articulados em níveis de complexidade crescente, para garantir a integralidade.", "explicacao": "Decreto 7.508/2011, art. 2º, VI."}, {"id": 2000004681, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que são os Protocolos Clínicos e Diretrizes Terapêuticas (PCDT)?", "verso": "Documentos que estabelecem critérios de diagnóstico, tratamento, medicamentos, posologias e acompanhamento de doenças no SUS.", "explicacao": "Decreto 7.508/2011, art. 2º, VIII."}, {"id": 2000004682, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "O que é a Comissão Intergestores Regional (CIR)?", "verso": "Instância de pactuação entre os gestores municipais de uma Região de Saúde e o gestor estadual.", "explicacao": "Decreto 7.508/2011, art. 30."}, {"id": 2000004683, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "pergunta", "frente": "Quais as comissões intergestores do SUS e seus participantes?", "verso": "CIT (União, estados e municípios, no âmbito nacional), CIB (estado e municípios) e CIR (região de saúde).", "explicacao": "Lei 8.080/1990, art. 14-A, e Decreto 7.508/2011."}, {"id": 2000004684, "trilha": "saude", "materia": "sus", "assunto": "LC 141", "tipo": "pergunta", "frente": "Qual o percentual mínimo que os municípios devem aplicar em saúde?", "verso": "15% da arrecadação de impostos e das transferências constitucionais.", "explicacao": "LC 141/2012, art. 7º. Estados: 12%."}, {"id": 2000004685, "trilha": "saude", "materia": "sus", "assunto": "LC 141", "tipo": "pergunta", "frente": "A merenda escolar conta como gasto em saúde para o piso constitucional?", "verso": "Não. A LC 141 exclui merenda escolar, saneamento custeado por tarifa, limpeza urbana e assistência social, entre outros.", "explicacao": "LC 141/2012, art. 4º."}, {"id": 2000004686, "trilha": "saude", "materia": "sus", "assunto": "LC 141", "tipo": "pergunta", "frente": "Qual o piso de aplicação da União em saúde após a EC 86/2015?", "verso": "15% da receita corrente líquida do exercício.", "explicacao": "CF, art. 198, § 2º, I."}, {"id": 2000004687, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é a coordenação do cuidado na atenção primária?", "verso": "A capacidade da APS de organizar e integrar o cuidado do usuário nos diferentes pontos da rede.", "explicacao": "Atributo de Starfield."}, {"id": 2000004688, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é a orientação comunitária na APS?", "verso": "Conhecer as necessidades de saúde da comunidade e o contexto social para planejar as ações.", "explicacao": "Atributo derivado da APS."}, {"id": 2000004689, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "Qual a carga horária semanal dos profissionais da equipe de Saúde da Família?", "verso": "40 horas semanais, em regra.", "explicacao": "PNAB (Portaria 2.436/2017)."}, {"id": 2000004690, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é a territorialização na atenção básica?", "verso": "Delimitação do território de atuação da equipe e conhecimento das famílias, das condições de vida e dos riscos.", "explicacao": "Base para o planejamento local."}, {"id": 2000004691, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é o Programa Saúde na Escola (PSE)?", "verso": "Programa intersetorial entre saúde e educação para ações de prevenção, promoção e atenção à saúde de estudantes da rede pública.", "explicacao": "Decreto 6.286/2007."}, {"id": 2000004692, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é o Consultório na Rua?", "verso": "Equipe da atenção básica que atende pessoas em situação de rua, de forma itinerante.", "explicacao": "Componente da PNAB."}, {"id": 2000004693, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que é a Rede de Atenção Psicossocial (RAPS)?", "verso": "Rede para pessoas com sofrimento ou transtorno mental e com necessidades decorrentes do uso de álcool e drogas.", "explicacao": "Inclui CAPS, residências terapêuticas e leitos em hospital geral."}, {"id": 2000004694, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que é a Rede de Cuidados à Pessoa com Deficiência?", "verso": "Rede que articula pontos de atenção para reabilitação física, auditiva, visual, intelectual e múltipla, como os CER (Centros Especializados em Reabilitação).", "explicacao": "Rede temática do SUS."}, {"id": 2000004695, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que são as UPAs 24h?", "verso": "Unidades de Pronto Atendimento de complexidade intermediária entre a atenção básica e a rede hospitalar.", "explicacao": "Componente da Rede de Urgência e Emergência."}, {"id": 2000004696, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que são os Serviços de Residência Terapêutica?", "verso": "Moradias para pessoas com transtorno mental egressas de longas internações psiquiátricas.", "explicacao": "Parte da RAPS e da desinstitucionalização."}, {"id": 2000004697, "trilha": "saude", "materia": "sus", "assunto": "Redes de atenção", "tipo": "pergunta", "frente": "O que é o Programa de Volta para Casa?", "verso": "Auxílio-reabilitação psicossocial pago a egressos de longas internações psiquiátricas.", "explicacao": "Lei 10.708/2003."}, {"id": 2000004698, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é vigilância ambiental em saúde?", "verso": "Ações de conhecimento e detecção de fatores do meio ambiente que interferem na saúde, como água, ar, solo e vetores.", "explicacao": "Integra a vigilância em saúde."}, {"id": 2000004699, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é investigação epidemiológica?", "verso": "Trabalho de campo para identificar a fonte de infecção, o modo de transmissão, os casos e os contatos, e propor medidas de controle.", "explicacao": "Feita a partir da notificação."}, {"id": 2000004700, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é bloqueio vacinal?", "verso": "Vacinação seletiva dos contatos de um caso suspeito para interromper a transmissão.", "explicacao": "Ex.: sarampo."}, {"id": 2000004701, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que são doenças de notificação compulsória imediata?", "verso": "Agravos que devem ser notificados em até 24 horas, como sarampo, raiva humana, febre amarela e casos de doença de origem desconhecida com potencial epidêmico.", "explicacao": "Lista nacional do Ministério da Saúde."}, {"id": 2000004702, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "A violência interpessoal e autoprovocada é de notificação compulsória?", "verso": "Sim. A violência sexual e a tentativa de suicídio são de notificação imediata ao serviço municipal.", "explicacao": "Lista nacional de notificação compulsória."}, {"id": 2000004703, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "Quem é obrigado a notificar doenças de notificação compulsória?", "verso": "Médicos, outros profissionais de saúde e responsáveis por serviços de saúde, públicos ou privados, e também estabelecimentos de ensino, entre outros.", "explicacao": "Lei 6.259/1975."}, {"id": 2000004704, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "Como se calcula o coeficiente de incidência?", "verso": "Casos novos no período ÷ população exposta × 10ⁿ.", "explicacao": "Ex.: 30 casos em 10.000 → 3 por 1.000."}, {"id": 2000004705, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "Como se calcula a taxa de letalidade?", "verso": "Óbitos pela doença ÷ número de casos da doença × 100.", "explicacao": "Mede a gravidade da doença."}, {"id": 2000004706, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "Em uma cidade com 3.000 nascidos vivos, ocorreram 45 óbitos de menores de 1 ano. Qual a taxa de mortalidade infantil?", "verso": "15 por 1.000 nascidos vivos.", "explicacao": "45 ÷ 3.000 × 1.000."}, {"id": 2000004707, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é o índice de Swaroop-Uemura?", "verso": "Proporção de óbitos de pessoas com 50 anos ou mais sobre o total de óbitos.", "explicacao": "Quanto maior, melhores as condições de saúde."}, {"id": 2000004708, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é a curva de Nelson de Moraes?", "verso": "Gráfico da mortalidade proporcional por faixas etárias, que indica o nível de saúde da população.", "explicacao": "Quanto mais óbitos em idosos, melhor o nível de saúde."}, {"id": 2000004709, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é um estudo ecológico?", "verso": "Estudo que analisa grupos ou populações, e não indivíduos, como comparar taxas entre municípios.", "explicacao": "Risco de falácia ecológica."}, {"id": 2000004710, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é o ensaio clínico randomizado?", "verso": "Estudo experimental em que os participantes são distribuídos aleatoriamente entre grupos de intervenção e controle.", "explicacao": "Padrão-ouro para avaliar tratamentos."}, {"id": 2000004711, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é o valor preditivo positivo de um teste?", "verso": "A probabilidade de a pessoa com teste positivo ter de fato a doença.", "explicacao": "Depende da prevalência da doença."}, {"id": 2000004712, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é risco relativo?", "verso": "A razão entre a incidência nos expostos e nos não expostos.", "explicacao": "RR > 1 indica associação com aumento de risco."}, {"id": 2000004713, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é a transição demográfica no Brasil?", "verso": "A queda da natalidade e da mortalidade, com envelhecimento da população.", "explicacao": "Ligada à transição epidemiológica."}, {"id": 2000004714, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Atenção Básica?", "verso": "A política que organiza a atenção básica e tem a Saúde da Família como estratégia prioritária.", "explicacao": "Portaria 2.436/2017, consolidada na Portaria de Consolidação 2/2017."}, {"id": 2000004715, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Atenção Integral à Saúde da Mulher?", "verso": "Política que amplia o cuidado à mulher além do ciclo gravídico-puerperal, incluindo saúde sexual, climatério e violência.", "explicacao": "Lançada em 2004."}, {"id": 2000004716, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Educação Permanente em Saúde?", "verso": "Estratégia de formação dos trabalhadores a partir dos problemas do cotidiano do trabalho em saúde.", "explicacao": "Portaria 198/2004."}, {"id": 2000004717, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Plantas Medicinais e Fitoterápicos?", "verso": "Política que busca garantir acesso seguro e uso racional de plantas medicinais e fitoterápicos.", "explicacao": "Decreto 5.813/2006."}, {"id": 2000004718, "trilha": "saude", "materia": "sus", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é o Plano de Saúde no SUS?", "verso": "Instrumento central de planejamento de cada esfera de gestão, com as intenções e resultados para 4 anos.", "explicacao": "Submetido ao Conselho de Saúde."}, {"id": 2000004719, "trilha": "saude", "materia": "sus", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é a Programação Anual de Saúde?", "verso": "Instrumento que operacionaliza o Plano de Saúde a cada ano, com ações, metas e recursos.", "explicacao": "Instrumento de planejamento do SUS."}, {"id": 2000004720, "trilha": "saude", "materia": "sus", "assunto": "Financiamento", "tipo": "pergunta", "frente": "O que é o Fundo Nacional de Saúde?", "verso": "Gestor financeiro dos recursos federais do SUS, que faz as transferências fundo a fundo para estados e municípios.", "explicacao": "Lei 8.142/1990."}, {"id": 2000004721, "trilha": "saude", "materia": "sus", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é a regionalização no SUS?", "verso": "Organização dos serviços em regiões de saúde, para racionalizar recursos e garantir acesso em todos os níveis de atenção.", "explicacao": "Princípio organizativo."}, {"id": 2000004722, "trilha": "saude", "materia": "sus", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é o Sisreg?", "verso": "Sistema de regulação do SUS que gerencia o acesso a consultas, exames e internações.", "explicacao": "Ferramenta das centrais de regulação."}, {"id": 2000004723, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que foi a Reforma Sanitária brasileira?", "verso": "Movimento dos anos 1970 e 1980 que defendia a saúde como direito e deu base à criação do SUS.", "explicacao": "Marco: 8ª Conferência Nacional de Saúde (1986)."}, {"id": 2000004724, "trilha": "saude", "materia": "sus", "assunto": "História", "tipo": "pergunta", "frente": "O que foi o SUDS?", "verso": "Sistema Unificado e Descentralizado de Saúde (1987), transição entre o modelo do Inamps e o SUS.", "explicacao": "Antecedeu o SUS."}, {"id": 2000004725, "trilha": "saude", "materia": "sus", "assunto": "Saúde suplementar", "tipo": "pergunta", "frente": "Os planos de saúde podem recusar cliente por doença preexistente?", "verso": "Não podem recusar, mas podem aplicar carência e cobertura parcial temporária para a doença preexistente declarada.", "explicacao": "Lei 9.656/1998."}, {"id": 2000004726, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Quais os principais fatores de risco para doença arterial coronariana?", "verso": "Hipertensão, diabetes, dislipidemia, tabagismo, obesidade, sedentarismo, idade e história familiar.", "explicacao": "Os modificáveis são alvo da prevenção."}, {"id": 2000004727, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Quais os sinais do edema agudo de pulmão?", "verso": "Dispneia intensa, ortopneia, estertores crepitantes, tosse com secreção rosada espumosa e sudorese.", "explicacao": "Emergência: oxigênio, cabeceira elevada, diurético e vasodilatador."}, {"id": 2000004728, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual o principal fator de risco para AVC?", "verso": "A hipertensão arterial.", "explicacao": "Também fibrilação atrial, diabetes e tabagismo."}, {"id": 2000004729, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Por que a fibrilação atrial aumenta o risco de AVC?", "verso": "Porque o sangue fica parado nos átrios e forma trombos que podem embolizar para o cérebro.", "explicacao": "Avalia-se a anticoagulação pelo escore CHA₂DS₂-VASc."}, {"id": 2000004730, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "O que é a crise hipertensiva com emergência?", "verso": "Elevação acentuada da pressão com lesão aguda de órgão-alvo, como AVC, infarto ou edema agudo de pulmão.", "explicacao": "Exige redução controlada em ambiente hospitalar."}, {"id": 2000004731, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual exame é essencial nos primeiros 10 minutos da dor torácica sugestiva de infarto?", "verso": "O eletrocardiograma.", "explicacao": "Diretrizes de síndrome coronariana aguda."}, {"id": 2000004732, "trilha": "saude", "materia": "med", "assunto": "Respiratório", "tipo": "pergunta", "frente": "Qual o tratamento de resgate na crise de asma?", "verso": "Broncodilatador de curta ação inalatório (como salbutamol), além de corticoide sistêmico nas crises moderadas a graves.", "explicacao": "Oxigênio se saturação baixa."}, {"id": 2000004733, "trilha": "saude", "materia": "med", "assunto": "Respiratório", "tipo": "pergunta", "frente": "Qual a principal causa de DPOC?", "verso": "O tabagismo.", "explicacao": "Também exposição à fumaça de lenha e poluentes ocupacionais."}, {"id": 2000004734, "trilha": "saude", "materia": "med", "assunto": "Respiratório", "tipo": "pergunta", "frente": "Quais os sintomas da covid-19 grave?", "verso": "Dispneia, saturação de oxigênio baixa, desconforto respiratório e piora do estado geral.", "explicacao": "Pode evoluir para síndrome respiratória aguda grave (SRAG)."}, {"id": 2000004735, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Qual o valor de hemoglobina glicada que confirma diabetes?", "verso": "Igual ou maior que 6,5%.", "explicacao": "Confirmado em segunda medida na ausência de sintomas inequívocos."}, {"id": 2000004736, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Quais as complicações crônicas do diabetes?", "verso": "Retinopatia, nefropatia, neuropatia, pé diabético e doenças cardiovasculares.", "explicacao": "Controle glicêmico e da pressão reduz o risco."}, {"id": 2000004737, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "O que é o estado hiperglicêmico hiperosmolar?", "verso": "Complicação aguda do diabetes tipo 2 com glicemia muito alta, desidratação intensa e alteração da consciência, sem cetoacidose importante.", "explicacao": "Comum em idosos."}, {"id": 2000004738, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "O que é síndrome metabólica?", "verso": "Conjunto de alterações como obesidade abdominal, hipertensão, glicemia elevada, triglicerídeos altos e HDL baixo.", "explicacao": "Aumenta o risco cardiovascular."}, {"id": 2000004739, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais os sinais de hemorragia digestiva alta?", "verso": "Hematêmese (vômito com sangue) e melena (fezes pretas, pastosas e fétidas).", "explicacao": "A hematoquezia (sangue vivo nas fezes) sugere origem baixa."}, {"id": 2000004740, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais os sintomas da doença do refluxo gastroesofágico?", "verso": "Pirose (azia) e regurgitação, que pioram após refeições e ao deitar.", "explicacao": "Medidas: elevar a cabeceira e evitar refeições antes de deitar."}, {"id": 2000004741, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais os sinais de abdome agudo?", "verso": "Dor abdominal intensa e súbita, com defesa abdominal, descompressão dolorosa (sinal de Blumberg) e, às vezes, febre e vômitos.", "explicacao": "Pode exigir cirurgia."}, {"id": 2000004742, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "O que é o sinal de Blumberg?", "verso": "Dor à descompressão brusca no ponto de McBurney, sugestivo de apendicite (irritação peritoneal).", "explicacao": "O ponto de McBurney fica no quadrante inferior direito."}, {"id": 2000004743, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "Quais as principais causas de doença renal crônica no Brasil?", "verso": "Hipertensão arterial e diabetes.", "explicacao": "Por isso o controle dessas doenças protege os rins."}, {"id": 2000004744, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "O que é a taxa de filtração glomerular?", "verso": "Medida da função dos rins, estimada pela creatinina, que define os estágios da doença renal crônica.", "explicacao": "Abaixo de 15 mL/min/1,73 m² é falência renal."}, {"id": 2000004745, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "Quais os sintomas da infecção urinária baixa (cistite)?", "verso": "Disúria, polaciúria, urgência urinária e dor suprapúbica.", "explicacao": "Febre e dor lombar sugerem pielonefrite."}, {"id": 2000004746, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Qual a janela de tempo para trombólise no AVC isquêmico?", "verso": "Até 4 horas e meia do início dos sintomas, em regra.", "explicacao": "Por isso é importante saber a hora de início."}, {"id": 2000004747, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os sinais de alerta de cefaleia grave (red flags)?", "verso": "Dor súbita e intensa (\"a pior da vida\"), com febre e rigidez de nuca, déficit neurológico, início após os 50 anos ou após trauma.", "explicacao": "Podem indicar hemorragia, meningite ou tumor."}, {"id": 2000004748, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é estado de mal epiléptico?", "verso": "Crise convulsiva que dura 5 minutos ou mais, ou crises repetidas sem recuperação da consciência entre elas.", "explicacao": "Emergência: benzodiazepínico."}, {"id": 2000004749, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Qual o primeiro sintoma mais comum da doença de Alzheimer?", "verso": "Perda de memória recente.", "explicacao": "Depois, outras funções cognitivas e a autonomia."}, {"id": 2000004750, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Como se transmite a hepatite B?", "verso": "Por sangue, relações sexuais e da mãe para o bebê (transmissão vertical).", "explicacao": "A vacina é a principal prevenção."}, {"id": 2000004751, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o agente da sífilis e como se transmite?", "verso": "A bactéria Treponema pallidum, transmitida por relações sexuais e da mãe para o feto.", "explicacao": "Tratamento com penicilina benzatina."}, {"id": 2000004752, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais as manifestações da sífilis primária?", "verso": "Cancro duro: úlcera única, indolor, de bordas endurecidas, no local da infecção.", "explicacao": "Desaparece sozinha, mas a doença continua."}, {"id": 2000004753, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais os sinais de meningite bacteriana?", "verso": "Febre, cefaleia intensa, rigidez de nuca, vômitos e alteração da consciência; petéquias sugerem meningococo.", "explicacao": "Emergência com antibiótico precoce."}, {"id": 2000004754, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Como se transmite a leptospirose?", "verso": "Pelo contato da pele ou mucosas com água ou lama contaminadas pela urina de ratos.", "explicacao": "Comum após enchentes."}, {"id": 2000004755, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o agente da hanseníase?", "verso": "Mycobacterium leprae (bacilo de Hansen).", "explicacao": "Tratamento com poliquimioterapia gratuita no SUS."}, {"id": 2000004756, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais os sinais clínicos da hanseníase?", "verso": "Manchas na pele com alteração de sensibilidade (térmica, dolorosa e tátil) e espessamento de nervos periféricos.", "explicacao": "Diagnóstico principalmente clínico."}, {"id": 2000004757, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "O que é a doença de Chagas e seu vetor?", "verso": "Doença causada pelo Trypanosoma cruzi, transmitida pelo barbeiro (triatomíneo), também por via oral (alimentos como açaí contaminado).", "explicacao": "Pode causar cardiopatia crônica."}, {"id": 2000004758, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Quais os sintomas da chikungunya?", "verso": "Febre alta e dores articulares intensas, que podem durar meses.", "explicacao": "Transmitida pelo Aedes aegypti."}, {"id": 2000004759, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual a principal complicação da zika na gestação?", "verso": "A microcefalia e outras malformações do bebê (síndrome congênita do zika).", "explicacao": "Transmitida pelo Aedes aegypti e por via sexual."}, {"id": 2000004760, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual a profilaxia antirrábica após mordedura de cão?", "verso": "Lavar o ferimento com água e sabão e avaliar a necessidade de vacina e soro conforme o tipo de exposição e o animal.", "explicacao": "Observar o cão por 10 dias, quando possível."}, {"id": 2000004761, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pergunta", "frente": "Quais os sintomas de anemia?", "verso": "Cansaço, palidez, falta de ar aos esforços, palpitação e tontura.", "explicacao": "A causa mais comum é deficiência de ferro."}, {"id": 2000004762, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pergunta", "frente": "O que é a trombocitopenia e seu risco?", "verso": "Plaquetas baixas, com risco de sangramentos, como petéquias e equimoses.", "explicacao": "Valor normal: 150.000 a 450.000/mm³."}, {"id": 2000004763, "trilha": "saude", "materia": "med", "assunto": "Oncologia", "tipo": "pergunta", "frente": "Quais os sinais de alerta para câncer?", "verso": "Perda de peso sem motivo, sangramentos anormais, nódulos, feridas que não cicatrizam, alteração de hábito intestinal e tosse persistente.", "explicacao": "Diagnóstico precoce melhora o prognóstico."}, {"id": 2000004764, "trilha": "saude", "materia": "med", "assunto": "Oncologia", "tipo": "pergunta", "frente": "Qual o câncer mais frequente na mulher brasileira, sem contar o de pele não melanoma?", "verso": "O câncer de mama.", "explicacao": "Estimativas do INCA."}, {"id": 2000004765, "trilha": "saude", "materia": "med", "assunto": "Oncologia", "tipo": "pergunta", "frente": "Qual o câncer mais frequente no homem brasileiro, sem contar o de pele não melanoma?", "verso": "O câncer de próstata.", "explicacao": "Estimativas do INCA."}, {"id": 2000004766, "trilha": "saude", "materia": "med", "assunto": "Oncologia", "tipo": "pergunta", "frente": "Qual vacina previne o câncer de colo do útero?", "verso": "A vacina contra o HPV.", "explicacao": "Oferecida pelo SUS a meninas e meninos na faixa etária recomendada."}, {"id": 2000004767, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os sinais de perigo na criança pela AIDPI?", "verso": "Não consegue beber ou mamar, vomita tudo, teve convulsões, está letárgica ou inconsciente.", "explicacao": "Exige referência urgente."}, {"id": 2000004768, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os sintomas da desnutrição grave do tipo kwashiorkor?", "verso": "Edema, alterações de pele e cabelo, irritabilidade e barriga inchada, por falta de proteínas.", "explicacao": "O marasmo é a desnutrição por falta global de calorias, com emagrecimento extremo."}, {"id": 2000004769, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Até quando se recomenda aleitamento materno exclusivo?", "verso": "Até os 6 meses.", "explicacao": "Depois, complementado até 2 anos ou mais."}, {"id": 2000004770, "trilha": "saude", "materia": "med", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "O que é a eclâmpsia?", "verso": "Convulsões em gestante com pré-eclâmpsia, sem outra causa.", "explicacao": "Tratamento com sulfato de magnésio."}, {"id": 2000004771, "trilha": "saude", "materia": "med", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "O que é a síndrome HELLP?", "verso": "Complicação da pré-eclâmpsia com hemólise, enzimas hepáticas elevadas e plaquetas baixas.", "explicacao": "Emergência obstétrica."}, {"id": 2000004772, "trilha": "saude", "materia": "med", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Qual o rastreamento de diabetes gestacional no pré-natal?", "verso": "Glicemia de jejum na primeira consulta e teste oral de tolerância à glicose entre 24 e 28 semanas.", "explicacao": "Diretrizes brasileiras."}, {"id": 2000004773, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os sintomas do transtorno de ansiedade generalizada?", "verso": "Preocupação excessiva e difícil de controlar por pelo menos 6 meses, com inquietação, cansaço, tensão muscular e insônia.", "explicacao": "Critérios do DSM."}, {"id": 2000004774, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os sintomas positivos da esquizofrenia?", "verso": "Delírios, alucinações e pensamento desorganizado.", "explicacao": "Sintomas negativos: apatia, isolamento e embotamento afetivo."}, {"id": 2000004775, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "O que é o transtorno afetivo bipolar?", "verso": "Transtorno com episódios de mania ou hipomania alternados com episódios depressivos.", "explicacao": "Tratado com estabilizadores de humor, como o lítio."}, {"id": 2000004776, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "O que é meia-vida de um medicamento?", "verso": "O tempo para a concentração do medicamento no sangue cair pela metade.", "explicacao": "Orienta o intervalo entre as doses."}, {"id": 2000004777, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "Por que os AINEs devem ser usados com cuidado em idosos?", "verso": "Pelo risco de sangramento gastrointestinal, piora da função renal e da pressão arterial.", "explicacao": "Ex.: ibuprofeno, diclofenaco."}, {"id": 2000004778, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "Qual o antídoto do paracetamol na intoxicação?", "verso": "N-acetilcisteína.", "explicacao": "A intoxicação causa lesão hepática."}, {"id": 2000004779, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "pergunta", "frente": "O que é interação medicamentosa?", "verso": "Quando um medicamento altera o efeito de outro, aumentando ou diminuindo sua ação ou toxicidade.", "explicacao": "Ex.: varfarina com vários antibióticos."}, {"id": 2000004780, "trilha": "saude", "materia": "med", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a conduta na suspeita de AVC no atendimento pré-hospitalar?", "verso": "Avaliar com a escala de Cincinnati ou SAMU, anotar a hora de início dos sintomas, medir a glicemia e levar rapidamente a hospital com capacidade para trombólise.", "explicacao": "Tempo é cérebro."}, {"id": 2000004781, "trilha": "saude", "materia": "med", "assunto": "Urgência", "tipo": "pergunta", "frente": "O que é a hipotermia e como se trata o paciente?", "verso": "Temperatura central abaixo de 35 °C. Remover roupas molhadas, aquecer gradualmente e evitar movimentos bruscos nos casos graves.", "explicacao": "Risco de arritmias."}, {"id": 2000004782, "trilha": "saude", "materia": "med", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a primeira medida no choque anafilático?", "verso": "Adrenalina intramuscular na face anterolateral da coxa.", "explicacao": "Depois, oxigênio, fluidos e demais medicamentos."}, {"id": 2000004783, "trilha": "saude", "materia": "med", "assunto": "Geriatria", "tipo": "pergunta", "frente": "O que são os medicamentos potencialmente inapropriados para idosos?", "verso": "Medicamentos com risco maior que o benefício em idosos, como benzodiazepínicos de longa ação, listados nos critérios de Beers.", "explicacao": "Aumentam o risco de quedas e confusão."}, {"id": 2000004784, "trilha": "saude", "materia": "med", "assunto": "Saúde do trabalhador", "tipo": "pergunta", "frente": "O que é a CAT?", "verso": "A Comunicação de Acidente de Trabalho, que deve ser emitida em caso de acidente ou doença do trabalho.", "explicacao": "Pode ser emitida pela empresa, pelo trabalhador, pelo médico ou pelo sindicato."}, {"id": 2000004785, "trilha": "saude", "materia": "med", "assunto": "Saúde do trabalhador", "tipo": "pergunta", "frente": "O que é a PAIR?", "verso": "Perda auditiva induzida por ruído, doença ocupacional causada por exposição prolongada a ruído intenso.", "explicacao": "Prevenção com protetores auriculares e controle do ruído."}, {"id": 2000004786, "trilha": "saude", "materia": "fisio", "assunto": "Profissão", "tipo": "pergunta", "frente": "Quais as atribuições privativas do fisioterapeuta pelo Decreto-Lei 938/1969?", "verso": "Executar métodos e técnicas fisioterápicos para restaurar, desenvolver e conservar a capacidade física do paciente.", "explicacao": "Decreto-Lei 938/1969, art. 3º."}, {"id": 2000004787, "trilha": "saude", "materia": "fisio", "assunto": "Profissão", "tipo": "pergunta", "frente": "O fisioterapeuta pode atuar com autonomia, sem encaminhamento médico?", "verso": "Sim. O COFFITO reconhece a autonomia do fisioterapeuta para avaliar, diagnosticar (diagnóstico cinético-funcional), prescrever e dar alta.", "explicacao": "Resolução COFFITO 80/1987 e normas posteriores."}, {"id": 2000004788, "trilha": "saude", "materia": "fisio", "assunto": "Profissão", "tipo": "pergunta", "frente": "O que é o diagnóstico cinético-funcional?", "verso": "Diagnóstico próprio do fisioterapeuta, sobre as alterações de movimento e de função do paciente.", "explicacao": "Base do plano de tratamento."}, {"id": 2000004789, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é a escala de Ashworth modificada?", "verso": "Escala que gradua a espasticidade pela resistência ao movimento passivo, de 0 a 4 (com o grau 1+).", "explicacao": "Usada em lesões neurológicas."}, {"id": 2000004790, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que avalia o teste de força de preensão manual?", "verso": "A força da mão, medida com dinamômetro, usada como indicador de força global e de fragilidade.", "explicacao": "Importante na avaliação de sarcopenia."}, {"id": 2000004791, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é a perimetria?", "verso": "A medida da circunferência de segmentos do corpo com fita métrica, para avaliar edema ou trofismo muscular.", "explicacao": "Comparar com o lado contralateral."}, {"id": 2000004792, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é a escala de Borg modificada?", "verso": "Escala de 0 a 10 para o paciente graduar a dispneia ou o esforço percebido.", "explicacao": "A original vai de 6 a 20."}, {"id": 2000004793, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que avalia o teste de sentar e levantar?", "verso": "A força e a resistência dos membros inferiores e a funcionalidade, contando as repetições em tempo definido.", "explicacao": "Muito usado em idosos."}, {"id": 2000004794, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é a Medida de Independência Funcional (MIF)?", "verso": "Instrumento que avalia o grau de independência em atividades motoras e cognitivas do dia a dia.", "explicacao": "Pontuação de 18 a 126."}, {"id": 2000004795, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "pergunta", "frente": "O que é a escala de Fugl-Meyer?", "verso": "Escala que avalia a recuperação motora, a sensibilidade e o equilíbrio após AVC.", "explicacao": "Muito usada em pesquisa e reabilitação neurológica."}, {"id": 2000004796, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste da gaveta anterior do joelho?", "verso": "A integridade do ligamento cruzado anterior.", "explicacao": "Teste de Lachman é mais sensível."}, {"id": 2000004797, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste da gaveta posterior do joelho?", "verso": "A integridade do ligamento cruzado posterior.", "explicacao": "A tíbia se desloca para trás."}, {"id": 2000004798, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de estresse em valgo do joelho?", "verso": "O ligamento colateral medial.", "explicacao": "O estresse em varo avalia o colateral lateral."}, {"id": 2000004799, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Thomas?", "verso": "O encurtamento dos flexores do quadril (iliopsoas).", "explicacao": "A coxa testada não consegue ficar apoiada na maca."}, {"id": 2000004800, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Trendelenburg?", "verso": "A fraqueza do glúteo médio: a pelve cai do lado oposto ao apoio.", "explicacao": "Comum em disfunções do quadril."}, {"id": 2000004801, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que avalia o teste de Tinel?", "verso": "Irritação de nervo: a percussão sobre o nervo provoca formigamento no seu trajeto, como no túnel do carpo.", "explicacao": "Junto com o Phalen."}, {"id": 2000004802, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a síndrome do túnel do carpo?", "verso": "Compressão do nervo mediano no punho, com dormência e formigamento nos três primeiros dedos.", "explicacao": "Comum em trabalhos repetitivos."}, {"id": 2000004803, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a epicondilite lateral?", "verso": "Inflamação ou degeneração dos tendões extensores do punho no epicôndilo lateral do cotovelo (\"cotovelo de tenista\").", "explicacao": "A medial é o \"cotovelo de golfista\"."}, {"id": 2000004804, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a capsulite adesiva (ombro congelado)?", "verso": "Inflamação e retração da cápsula do ombro, com dor e perda progressiva do movimento, em fases dolorosa, de rigidez e de descongelamento.", "explicacao": "Comum em diabéticos."}, {"id": 2000004805, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a fascite plantar?", "verso": "Inflamação da fáscia plantar, com dor no calcanhar ao dar os primeiros passos pela manhã.", "explicacao": "Tratada com alongamentos e palmilhas."}, {"id": 2000004806, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a tendinopatia patelar?", "verso": "Lesão do tendão patelar por sobrecarga, comum em esportes de salto (\"joelho de saltador\").", "explicacao": "Exercícios excêntricos são indicados."}, {"id": 2000004807, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "Qual o objetivo da fisioterapia precoce após reconstrução do LCA?", "verso": "Controlar dor e edema, recuperar a extensão completa do joelho, ativar o quadríceps e progredir a carga com segurança.", "explicacao": "Reabilitação por fases."}, {"id": 2000004808, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a hérnia de disco lombar e seu sinal clássico?", "verso": "Saída do núcleo pulposo pelo ânulo fibroso, comprimindo raízes nervosas, com dor irradiada para a perna (ciatalgia).", "explicacao": "Teste de Lasègue positivo."}, {"id": 2000004809, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é o método McKenzie?", "verso": "Abordagem de avaliação e tratamento da coluna baseada em movimentos repetidos e na centralização da dor.", "explicacao": "Usado em dores lombares e cervicais."}, {"id": 2000004810, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a cinesioterapia?", "verso": "Uso terapêutico do movimento e do exercício.", "explicacao": "Inclui alongamentos, fortalecimento e treino funcional."}, {"id": 2000004811, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pares", "frente": "Qual a diferença entre exercício passivo, ativo-assistido, ativo livre e resistido?", "verso": "Passivo: o terapeuta move o segmento. Ativo-assistido: o paciente move com ajuda. Ativo livre: move sozinho contra a gravidade. Resistido: move contra resistência externa.", "explicacao": "Progressão da cinesioterapia."}, {"id": 2000004812, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "Por quanto tempo se recomenda manter um alongamento estático?", "verso": "Cerca de 15 a 30 segundos, repetido algumas vezes.", "explicacao": "Ganhos de flexibilidade."}, {"id": 2000004813, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os sinais de lesão do neurônio motor superior?", "verso": "Espasticidade, hiper-reflexia, sinal de Babinski e fraqueza sem atrofia importante.", "explicacao": "Ex.: AVC, lesão medular."}, {"id": 2000004814, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os sinais de lesão do neurônio motor inferior?", "verso": "Flacidez, hiporreflexia ou arreflexia, atrofia muscular e fasciculações.", "explicacao": "Ex.: lesão de nervo periférico."}, {"id": 2000004815, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é o sinal de Babinski?", "verso": "Extensão do hálux ao estimular a planta do pé, indicando lesão do trato piramidal no adulto.", "explicacao": "Normal em bebês até cerca de 1 ano e meio."}, {"id": 2000004816, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a ataxia?", "verso": "Falta de coordenação dos movimentos, comum em lesões cerebelares.", "explicacao": "Avaliada pelos testes índex-nariz e calcanhar-joelho."}, {"id": 2000004817, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a escala ASIA?", "verso": "Escala que classifica a lesão medular quanto ao nível e à gravidade (completa ou incompleta), de A a E.", "explicacao": "A: lesão completa; E: função normal."}, {"id": 2000004818, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Por que o paciente com lesão medular deve mudar de posição com frequência?", "verso": "Para prevenir lesões por pressão, pela perda de sensibilidade e mobilidade.", "explicacao": "Também prevenir contraturas."}, {"id": 2000004819, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a esclerose lateral amiotrófica (ELA)?", "verso": "Doença degenerativa que afeta os neurônios motores superiores e inferiores, com fraqueza progressiva.", "explicacao": "A fisioterapia mantém função e respiração."}, {"id": 2000004820, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a esclerose múltipla?", "verso": "Doença autoimune desmielinizante do sistema nervoso central, com surtos e remissões de sintomas como fraqueza, fadiga e alterações visuais.", "explicacao": "O calor costuma piorar os sintomas."}, {"id": 2000004821, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "Quais os objetivos da fisioterapia no AVC agudo?", "verso": "Posicionamento adequado, prevenção de complicações (pneumonia, lesão por pressão, ombro doloroso), mobilização precoce e estímulo ao lado afetado.", "explicacao": "Reabilitação começa cedo."}, {"id": 2000004822, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é o ombro doloroso do hemiplégico?", "verso": "Dor no ombro do lado afetado após AVC, muitas vezes por subluxação e manejo inadequado do braço.", "explicacao": "Prevenir com posicionamento e apoio do braço."}, {"id": 2000004823, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a heminegligência?", "verso": "Quando o paciente ignora um lado do corpo e do espaço, geralmente o esquerdo, após lesão do hemisfério direito.", "explicacao": "Estimular o lado negligenciado."}, {"id": 2000004824, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a capacidade vital?", "verso": "O volume máximo de ar que se expira após uma inspiração máxima.", "explicacao": "Reduzida em doenças restritivas e neuromusculares."}, {"id": 2000004825, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Para que serve a espirometria?", "verso": "Medir volumes e fluxos pulmonares e diagnosticar distúrbios obstrutivos e restritivos.", "explicacao": "A relação VEF1/CVF baixa indica obstrução."}, {"id": 2000004826, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a tosse assistida?", "verso": "Técnica em que o fisioterapeuta comprime o abdome ou o tórax durante a tosse, para aumentar sua eficácia.", "explicacao": "Útil em pacientes com fraqueza muscular."}, {"id": 2000004827, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é o treinamento muscular inspiratório?", "verso": "Exercício com dispositivo de carga resistida para fortalecer os músculos inspiratórios.", "explicacao": "Usado na DPOC e no desmame."}, {"id": 2000004828, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a pressão inspiratória máxima (PImáx)?", "verso": "Medida da força dos músculos inspiratórios, feita com manovacuômetro.", "explicacao": "Valores baixos indicam fraqueza respiratória."}, {"id": 2000004829, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a ventilação controlada a volume e a pressão?", "verso": "Volume: o ventilador garante o volume corrente, e a pressão varia. Pressão: garante a pressão, e o volume varia conforme a mecânica pulmonar.", "explicacao": "Modos básicos da ventilação mecânica."}, {"id": 2000004830, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a pressão de platô e qual o limite recomendado?", "verso": "Pressão nos alvéolos ao fim da inspiração, que deve ficar abaixo de 30 cmH₂O para proteger o pulmão.", "explicacao": "Estratégia de ventilação protetora."}, {"id": 2000004831, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a FiO₂?", "verso": "A fração de oxigênio no ar inspirado: 21% no ar ambiente e até 100% no ventilador.", "explicacao": "Ajustada para manter a saturação alvo."}, {"id": 2000004832, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a pressão de suporte (PSV)?", "verso": "Modo ventilatório espontâneo em que o ventilador ajuda cada inspiração com uma pressão definida.", "explicacao": "Muito usado no desmame."}, {"id": 2000004833, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a pneumonia associada à ventilação mecânica e como prevenir?", "verso": "Pneumonia após 48 h de ventilação. Prevenção: cabeceira elevada, higiene oral com clorexidina conforme protocolo, pressão do cuff adequada e avaliação diária de desmame.", "explicacao": "Bundle de prevenção."}, {"id": 2000004834, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "Qual a posição que melhora a oxigenação no paciente com pneumonia unilateral?", "verso": "Deitar com o pulmão sadio para baixo (\"good lung down\").", "explicacao": "Melhora a relação ventilação-perfusão."}, {"id": 2000004835, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a fisioterapia respiratória na bronquiolite?", "verso": "Uso criterioso de técnicas de desobstrução e aspiração de vias aéreas superiores, sem rotina de técnicas convencionais de tapotagem.", "explicacao": "Seguir as evidências atuais."}, {"id": 2000004836, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "Qual a fórmula de Karvonen?", "verso": "FC de treino = FC repouso + % × (FCmáx − FC repouso).", "explicacao": "Usa a frequência cardíaca de reserva."}, {"id": 2000004837, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "Qual a frequência de treino a 60% pela fórmula de Karvonen para 40 anos e FC de repouso 70 bpm?", "verso": "136 bpm.", "explicacao": "FCmáx 180; reserva 110; 70 + 0,6 × 110 = 136."}, {"id": 2000004838, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "Quando interromper o exercício na reabilitação cardíaca?", "verso": "Em caso de dor no peito, dispneia desproporcional, tontura, queda da pressão arterial com o esforço, arritmias ou sinais de baixo débito.", "explicacao": "Monitorar sinais vitais e esforço percebido."}, {"id": 2000004839, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "O que é a doença arterial obstrutiva periférica e seu sintoma clássico?", "verso": "Estreitamento das artérias dos membros, com claudicação intermitente (dor na panturrilha ao caminhar que melhora com repouso).", "explicacao": "Treino de caminhada supervisionado melhora a distância."}, {"id": 2000004840, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "pergunta", "frente": "O que é o linfedema e como se trata?", "verso": "Acúmulo de linfa por falha da drenagem linfática, tratado com terapia física complexa: drenagem linfática manual, compressão, exercícios e cuidados com a pele.", "explicacao": "Comum após esvaziamento axilar."}, {"id": 2000004841, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "O que é o ultrassom terapêutico e seu efeito térmico?", "verso": "Ondas mecânicas de alta frequência que, no modo contínuo, aquecem tecidos profundos.", "explicacao": "O pulsado tem efeito mais mecânico (não térmico)."}, {"id": 2000004842, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "Qual a principal contraindicação do ultrassom terapêutico?", "verso": "Aplicação sobre útero gravídico, tumores, olhos, áreas com trombose e placas de crescimento em crianças.", "explicacao": "Também evitar sobre marca-passo."}, {"id": 2000004843, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "Qual a principal contraindicação da eletroterapia?", "verso": "Pacientes com marca-passo cardíaco (próximo ao tórax), além de gestantes no abdome, áreas com trombose e tumores.", "explicacao": "Avaliar sempre as contraindicações."}, {"id": 2000004844, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "O que é a teoria das comportas da dor?", "verso": "A estimulação de fibras sensitivas grossas (tato) bloqueia a transmissão da dor na medula.", "explicacao": "Explica o efeito do TENS convencional."}, {"id": 2000004845, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "Quais os efeitos fisiológicos do calor superficial?", "verso": "Vasodilatação, relaxamento muscular, aumento da extensibilidade do colágeno e alívio da dor.", "explicacao": "Evitar na fase aguda da inflamação."}, {"id": 2000004846, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "Quais os efeitos fisiológicos do frio (crioterapia)?", "verso": "Vasoconstrição, redução do edema, da dor, do espasmo e do metabolismo local.", "explicacao": "Indicado na fase aguda."}, {"id": 2000004847, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "O que é a corrente interferencial?", "verso": "Corrente de média frequência que se cruza nos tecidos e gera uma frequência baixa resultante, usada para analgesia profunda.", "explicacao": "Mais confortável na pele."}, {"id": 2000004848, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "pergunta", "frente": "O que é a corrente russa?", "verso": "Corrente de média frequência usada para fortalecimento muscular por estimulação elétrica.", "explicacao": "Eletroestimulação neuromuscular."}, {"id": 2000004849, "trilha": "saude", "materia": "fisio", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "O que é a incontinência urinária de esforço?", "verso": "Perda de urina ao tossir, espirrar ou fazer esforço, por fraqueza do assoalho pélvico.", "explicacao": "Fisioterapia pélvica é primeira linha."}, {"id": 2000004850, "trilha": "saude", "materia": "fisio", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Quais os benefícios do exercício físico na gestação sem complicações?", "verso": "Melhor controle do peso e da glicemia, menos dor lombar, melhor condicionamento e humor.", "explicacao": "Atividade moderada é recomendada."}, {"id": 2000004851, "trilha": "saude", "materia": "fisio", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "O que é a diástase dos retos abdominais?", "verso": "Afastamento dos músculos retos abdominais na linha alba, comum na gestação e no pós-parto.", "explicacao": "Tratada com exercícios orientados."}, {"id": 2000004852, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os marcos motores esperados no primeiro ano de vida?", "verso": "Sustentar a cabeça (3 meses), rolar (4-6 meses), sentar sem apoio (6-8 meses), engatinhar (8-10 meses) e andar (12-15 meses).", "explicacao": "Atrasos devem ser avaliados."}, {"id": 2000004853, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "O que é o reflexo de Moro?", "verso": "Reação de susto do bebê: abre os braços e depois os fecha diante de queda súbita da cabeça.", "explicacao": "Desaparece por volta dos 4 a 6 meses."}, {"id": 2000004854, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "O que é o torcicolo muscular congênito?", "verso": "Encurtamento do músculo esternocleidomastóideo no bebê, que inclina a cabeça para um lado e gira para o outro.", "explicacao": "Tratado com alongamento e posicionamento."}, {"id": 2000004855, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "O que é a displasia do desenvolvimento do quadril?", "verso": "Alteração na formação do quadril do bebê, avaliada pelas manobras de Ortolani e Barlow.", "explicacao": "Tratamento precoce com suspensório de Pavlik."}, {"id": 2000004856, "trilha": "saude", "materia": "fisio", "assunto": "Geriatria", "tipo": "pergunta", "frente": "O que é a síndrome da fragilidade no idoso?", "verso": "Estado de vulnerabilidade com perda de peso, fraqueza, lentidão na marcha, baixa atividade física e exaustão.", "explicacao": "Critérios de Fried."}, {"id": 2000004857, "trilha": "saude", "materia": "fisio", "assunto": "Geriatria", "tipo": "pergunta", "frente": "Que tipo de exercício mais ajuda a prevenir quedas em idosos?", "verso": "Exercícios de equilíbrio e fortalecimento, praticados regularmente.", "explicacao": "Também revisão de medicamentos e do ambiente."}, {"id": 2000004858, "trilha": "saude", "materia": "fisio", "assunto": "Geriatria", "tipo": "pergunta", "frente": "Por que o exercício resistido é importante na osteoporose?", "verso": "Porque estimula a formação óssea e fortalece os músculos, reduzindo o risco de quedas e fraturas.", "explicacao": "Evitar flexão excessiva da coluna com carga."}, {"id": 2000004859, "trilha": "saude", "materia": "fisio", "assunto": "Saúde do trabalhador", "tipo": "pergunta", "frente": "O que é a ginástica laboral?", "verso": "Exercícios realizados no local de trabalho para prevenir lesões e reduzir a fadiga.", "explicacao": "Pode ser preparatória, compensatória ou de relaxamento."}, {"id": 2000004860, "trilha": "saude", "materia": "fisio", "assunto": "Saúde do trabalhador", "tipo": "pergunta", "frente": "O que é análise ergonômica do trabalho?", "verso": "Avaliação das condições de trabalho (postura, mobiliário, ritmo, organização) para adaptá-las ao trabalhador.", "explicacao": "NR-17."}, {"id": 2000004861, "trilha": "saude", "materia": "fisio", "assunto": "Órteses e próteses", "tipo": "pares", "frente": "Qual a diferença entre órtese e prótese?", "verso": "Órtese: dispositivo que apoia ou corrige uma parte do corpo (tala, colete). Prótese: substitui uma parte ausente (membro artificial).", "explicacao": "O fisioterapeuta treina o uso."}, {"id": 2000004862, "trilha": "saude", "materia": "fisio", "assunto": "Órteses e próteses", "tipo": "pergunta", "frente": "Como se ajusta a altura da bengala?", "verso": "A empunhadura deve ficar na altura do trocânter maior (ou do punho com o braço estendido), com o cotovelo levemente fletido (cerca de 20° a 30°).", "explicacao": "Usar do lado oposto ao membro afetado."}, {"id": 2000004863, "trilha": "saude", "materia": "fisio", "assunto": "Órteses e próteses", "tipo": "pergunta", "frente": "Como se sobe escadas com muleta ou bengala, em regra?", "verso": "Sobe primeiro a perna boa, depois a muleta e a perna afetada. Para descer, vai primeiro a muleta com a perna afetada.", "explicacao": "\"Sobe com a boa, desce com a ruim\"."}, {"id": 2000004864, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "certo_errado", "frente": "Certo ou errado? A vacina BCG deve ser aplicada no braço esquerdo.", "verso": "Errado. É aplicada na inserção inferior do deltoide direito.", "explicacao": "Padronização para facilitar a identificação da cicatriz."}, {"id": 2000004865, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "certo_errado", "frente": "Certo ou errado? Pode-se administrar cloreto de potássio concentrado em bolus intravenoso.", "verso": "Errado. Deve ser sempre diluído e infundido lentamente; em bolus pode causar parada cardíaca.", "explicacao": "Medicamento de alta vigilância."}, {"id": 2000004866, "trilha": "saude", "materia": "enf", "assunto": "Sinais vitais", "tipo": "certo_errado", "frente": "Certo ou errado? A pressão arterial deve ser medida logo após o paciente subir escadas.", "verso": "Errado. O paciente deve repousar pelo menos 5 minutos, sem ter fumado, ingerido cafeína ou feito exercício nos 30 minutos anteriores.", "explicacao": "Diretrizes de medida da pressão."}, {"id": 2000004867, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "certo_errado", "frente": "Certo ou errado? Após um acidente com agulha, deve-se espremer o local para sair sangue.", "verso": "Errado. Deve-se lavar com água e sabão, sem espremer, e procurar atendimento para avaliar a profilaxia.", "explicacao": "Exposição a material biológico."}, {"id": 2000004868, "trilha": "saude", "materia": "enf", "assunto": "Biossegurança", "tipo": "certo_errado", "frente": "Certo ou errado? A agulha usada deve ser reencapada antes do descarte.", "verso": "Errado. Não se reencapa agulha; descarta-se direto na caixa de perfurocortantes.", "explicacao": "NR-32."}, {"id": 2000004869, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "certo_errado", "frente": "Certo ou errado? Uma ferida deve ficar seca para cicatrizar melhor.", "verso": "Errado. O meio úmido favorece a cicatrização.", "explicacao": "Princípio da terapia tópica moderna."}, {"id": 2000004870, "trilha": "saude", "materia": "enf", "assunto": "Neonatologia", "tipo": "certo_errado", "frente": "Certo ou errado? O recém-nascido deve tomar banho logo ao nascer, antes do contato com a mãe.", "verso": "Errado. Recomenda-se o contato pele a pele imediato e adiar o banho, para evitar hipotermia e favorecer a amamentação.", "explicacao": "Boas práticas de atenção ao parto."}, {"id": 2000004871, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "certo_errado", "frente": "Certo ou errado? Perguntar a alguém se tem pensamentos suicidas aumenta o risco de suicídio.", "verso": "Errado. Perguntar diretamente ajuda a identificar o risco e a pessoa a buscar ajuda.", "explicacao": "Abordagem recomendada pelo Ministério da Saúde."}, {"id": 2000004872, "trilha": "saude", "materia": "enf", "assunto": "Hemoterapia", "tipo": "certo_errado", "frente": "Certo ou errado? Pode-se infundir soro glicosado junto com o concentrado de hemácias.", "verso": "Errado. Só soro fisiológico 0,9%, pois o glicosado pode causar hemólise.", "explicacao": "Normas de hemoterapia."}, {"id": 2000004873, "trilha": "saude", "materia": "enf", "assunto": "Nutrição", "tipo": "lacuna", "frente": "\"Durante a dieta enteral, a cabeceira deve ficar elevada entre 30° e ____.\"", "verso": "45°", "explicacao": "Prevenção de broncoaspiração."}, {"id": 2000004874, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "lacuna", "frente": "\"Para microgotas, o número de microgotas por minuto é igual ao volume dividido pelo número de ____.\"", "verso": "horas", "explicacao": "Ex.: 120 mL em 2 h = 60 microgotas/min."}, {"id": 2000004875, "trilha": "saude", "materia": "enf", "assunto": "Imunização", "tipo": "lacuna", "frente": "\"As vacinas de rotina devem ser conservadas entre +2 °C e ____.\"", "verso": "+8 °C", "explicacao": "Rede de frio."}, {"id": 2000004876, "trilha": "saude", "materia": "enf", "assunto": "Segurança do paciente", "tipo": "lacuna", "frente": "\"Antes de qualquer procedimento, o paciente deve ser identificado com pelo menos ____ identificadores.\"", "verso": "dois", "explicacao": "Ex.: nome completo e data de nascimento."}, {"id": 2000004877, "trilha": "saude", "materia": "sus", "assunto": "Princípios", "tipo": "certo_errado", "frente": "Certo ou errado? A universalidade significa que só quem contribui para a previdência tem direito ao SUS.", "verso": "Errado. O SUS é para todos, sem exigir contribuição.", "explicacao": "CF, art. 196."}, {"id": 2000004878, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.142", "tipo": "certo_errado", "frente": "Certo ou errado? Os Conselhos de Saúde têm caráter apenas consultivo.", "verso": "Errado. Têm caráter permanente e deliberativo.", "explicacao": "Lei 8.142/1990, art. 1º, § 2º."}, {"id": 2000004879, "trilha": "saude", "materia": "sus", "assunto": "Constituição", "tipo": "certo_errado", "frente": "Certo ou errado? As instituições privadas com fins lucrativos podem receber auxílios e subvenções públicas para a saúde.", "verso": "Errado. É vedada a destinação de recursos públicos para auxílios ou subvenções a instituições privadas com fins lucrativos.", "explicacao": "CF, art. 199, § 2º."}, {"id": 2000004880, "trilha": "saude", "materia": "sus", "assunto": "Decreto 7.508", "tipo": "certo_errado", "frente": "Certo ou errado? A atenção primária é uma das portas de entrada do SUS.", "verso": "Certo. Também são portas de entrada a urgência e emergência, a atenção psicossocial e os serviços especiais de acesso aberto.", "explicacao": "Decreto 7.508/2011, art. 9º."}, {"id": 2000004881, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "certo_errado", "frente": "Certo ou errado? Prevalência é o número de casos novos em um período.", "verso": "Errado. Esse é o conceito de incidência. Prevalência é o total de casos existentes.", "explicacao": "Conceitos básicos."}, {"id": 2000004882, "trilha": "saude", "materia": "sus", "assunto": "Lei 8.080", "tipo": "lacuna", "frente": "\"A saúde é um direito fundamental do ser humano, devendo o ____ prover as condições indispensáveis ao seu pleno exercício.\"", "verso": "Estado", "explicacao": "Lei 8.080/1990, art. 2º."}, {"id": 2000004883, "trilha": "saude", "materia": "sus", "assunto": "LC 141", "tipo": "lacuna", "frente": "\"Os estados devem aplicar, no mínimo, ____% da arrecadação de impostos em ações e serviços públicos de saúde.\"", "verso": "12", "explicacao": "LC 141/2012, art. 6º. Municípios: 15%."}, {"id": 2000004884, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "certo_errado", "frente": "Certo ou errado? A hipertensão arterial costuma ter muitos sintomas no início.", "verso": "Errado. Na maioria das vezes é silenciosa, por isso a medida regular é importante.", "explicacao": "\"Assassina silenciosa\"."}, {"id": 2000004885, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "certo_errado", "frente": "Certo ou errado? Antibióticos devem ser usados para tratar gripe.", "verso": "Errado. A gripe é causada por vírus, e antibióticos não agem contra vírus.", "explicacao": "Uso inadequado favorece resistência bacteriana."}, {"id": 2000004886, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "certo_errado", "frente": "Certo ou errado? A tuberculose é transmitida pelo compartilhamento de talheres.", "verso": "Errado. É transmitida pelo ar, por gotículas e aerossóis eliminados ao tossir, falar ou espirrar.", "explicacao": "Objetos não transmitem."}, {"id": 2000004887, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "certo_errado", "frente": "Certo ou errado? O diabetes tipo 2 é sempre tratado com insulina desde o diagnóstico.", "verso": "Errado. Em geral começa com mudança de estilo de vida e metformina; a insulina pode ser necessária depois.", "explicacao": "Diretrizes da Sociedade Brasileira de Diabetes."}, {"id": 2000004888, "trilha": "saude", "materia": "med", "assunto": "Urgência", "tipo": "certo_errado", "frente": "Certo ou errado? Na convulsão, deve-se colocar um objeto na boca do paciente para ele não engolir a língua.", "verso": "Errado. Não se coloca nada na boca; protege-se a cabeça e lateraliza-se o paciente.", "explicacao": "Risco de lesão e obstrução."}, {"id": 2000004889, "trilha": "saude", "materia": "med", "assunto": "Farmacologia", "tipo": "lacuna", "frente": "\"O antídoto da intoxicação por paracetamol é a ____.\"", "verso": "N-acetilcisteína", "explicacao": "Proteção hepática."}, {"id": 2000004890, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "certo_errado", "frente": "Certo ou errado? A ventilação não invasiva é indicada em paciente inconsciente sem proteção de vias aéreas.", "verso": "Errado. Rebaixamento de consciência sem proteção das vias aéreas é contraindicação.", "explicacao": "Também contraindicada em vômitos incoercíveis e instabilidade grave."}, {"id": 2000004891, "trilha": "saude", "materia": "fisio", "assunto": "Eletrotermofototerapia", "tipo": "certo_errado", "frente": "Certo ou errado? O calor é indicado nas primeiras horas de uma entorse com edema.", "verso": "Errado. Na fase aguda, usa-se o frio. O calor aumenta o edema.", "explicacao": "Protocolo PRICE ou POLICE."}, {"id": 2000004892, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "certo_errado", "frente": "Certo ou errado? O repouso absoluto prolongado é o melhor tratamento para a dor lombar comum.", "verso": "Errado. Manter-se ativo e fazer exercícios orientados é mais eficaz.", "explicacao": "Diretrizes atuais de lombalgia."}, {"id": 2000004893, "trilha": "saude", "materia": "fisio", "assunto": "Avaliação", "tipo": "lacuna", "frente": "\"Na escala de força muscular, o grau ____ corresponde à força normal contra resistência máxima.\"", "verso": "5", "explicacao": "Escala de 0 a 5 (MRC/Oxford)."}, {"id": 2000004894, "trilha": "saude", "materia": "fisio", "assunto": "Cardiovascular", "tipo": "lacuna", "frente": "\"A frequência cardíaca máxima estimada pela fórmula clássica é 220 menos a ____.\"", "verso": "idade", "explicacao": "Ex.: 50 anos → 170 bpm."}, {"id": 2000004895, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "O que é o transtorno de estresse pós-traumático?", "verso": "Transtorno após evento traumático, com revivescências (flashbacks), evitação, alterações de humor e hipervigilância por mais de 1 mês.", "explicacao": "Comum após violência e desastres."}, {"id": 2000004896, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os sinais de intoxicação por opioides?", "verso": "Miose (pupilas puntiformes), depressão respiratória e rebaixamento da consciência.", "explicacao": "Antídoto: naloxona."}, {"id": 2000004897, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Quais os sinais do hipotireoidismo?", "verso": "Cansaço, ganho de peso, intolerância ao frio, pele seca, constipação e lentidão.", "explicacao": "TSH elevado no hipotireoidismo primário."}, {"id": 2000004898, "trilha": "saude", "materia": "med", "assunto": "Dermatologia", "tipo": "pergunta", "frente": "O que é a escabiose (sarna) e como se transmite?", "verso": "Infestação da pele pelo ácaro Sarcoptes scabiei, com coceira intensa à noite, transmitida por contato pessoal e roupas.", "explicacao": "Tratar os contatos ao mesmo tempo."}, {"id": 2000004899, "trilha": "saude", "materia": "med", "assunto": "Dermatologia", "tipo": "pergunta", "frente": "O que é a pediculose?", "verso": "Infestação por piolhos, comum no couro cabeludo de crianças.", "explicacao": "Tratamento com produto específico e pente fino."}, {"id": 2000004900, "trilha": "saude", "materia": "med", "assunto": "Oftalmologia", "tipo": "pergunta", "frente": "O que é a conjuntivite e como se previne a transmissão?", "verso": "Inflamação da conjuntiva, com olho vermelho e secreção. Prevenção: lavar as mãos e não compartilhar toalhas e colírios.", "explicacao": "A viral é muito contagiosa."}, {"id": 2000004901, "trilha": "saude", "materia": "med", "assunto": "Otorrinolaringologia", "tipo": "pergunta", "frente": "Qual o agente mais comum da faringoamigdalite bacteriana?", "verso": "O estreptococo beta-hemolítico do grupo A.", "explicacao": "Tratamento com penicilina previne a febre reumática."}, {"id": 2000004902, "trilha": "saude", "materia": "med", "assunto": "Reumatologia", "tipo": "pergunta", "frente": "O que é a febre reumática?", "verso": "Complicação de faringite por estreptococo não tratada, que pode lesar as válvulas do coração.", "explicacao": "Prevenida com penicilina benzatina."}, {"id": 2000004903, "trilha": "saude", "materia": "med", "assunto": "Ginecologia", "tipo": "pergunta", "frente": "Quais os sintomas da menopausa?", "verso": "Fogachos (ondas de calor), suores noturnos, alterações do sono e do humor e secura vaginal.", "explicacao": "Diagnóstico após 12 meses sem menstruação."}, {"id": 2000004904, "trilha": "saude", "materia": "med", "assunto": "Urologia", "tipo": "pergunta", "frente": "Qual o exame de rastreamento do câncer de próstata e qual a posição do Ministério da Saúde?", "verso": "O PSA e o toque retal; o Ministério da Saúde não recomenda o rastreamento populacional de rotina, e sim a decisão compartilhada.", "explicacao": "Pelo risco de sobrediagnóstico."}, {"id": 2000004905, "trilha": "saude", "materia": "med", "assunto": "Nutrição", "tipo": "pergunta", "frente": "Qual a classificação do IMC pela OMS para adultos?", "verso": "Abaixo de 18,5: baixo peso. 18,5 a 24,9: normal. 25 a 29,9: sobrepeso. 30 ou mais: obesidade.", "explicacao": "Obesidade grau III: 40 ou mais."}, {"id": 2000004906, "trilha": "saude", "materia": "med", "assunto": "Pneumologia", "tipo": "pergunta", "frente": "O que é a síndrome da apneia obstrutiva do sono?", "verso": "Paradas repetidas da respiração durante o sono por obstrução das vias aéreas, com ronco e sonolência diurna.", "explicacao": "Tratada com CPAP."}, {"id": 2000004907, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a conduta na obstrução de vias aéreas por corpo estranho em lactente consciente?", "verso": "5 golpes nas costas alternados com 5 compressões torácicas, com o bebê de bruços e depois de barriga para cima, apoiado no antebraço.", "explicacao": "Não fazer a manobra de Heimlich abdominal em bebês."}, {"id": 2000004908, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a relação compressão-ventilação na RCP pediátrica com dois socorristas?", "verso": "15 compressões para 2 ventilações.", "explicacao": "Com um socorrista, 30:2."}, {"id": 2000004909, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a profundidade das compressões torácicas no lactente?", "verso": "Cerca de 4 cm (um terço do diâmetro do tórax).", "explicacao": "Com dois dedos ou dois polegares."}, {"id": 2000004910, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "O que fazer com um dente permanente arrancado em trauma?", "verso": "Segurar pela coroa, não esfregar a raiz, recolocar se possível ou guardar em leite ou soro e procurar dentista com urgência.", "explicacao": "Quanto antes, maior a chance de reimplante."}, {"id": 2000004911, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a conduta em hemorragia nasal (epistaxe) simples?", "verso": "Sentar o paciente com a cabeça levemente inclinada para a frente e comprimir as narinas por cerca de 10 minutos.", "explicacao": "Não inclinar a cabeça para trás."}, {"id": 2000004912, "trilha": "saude", "materia": "enf", "assunto": "Urgência", "tipo": "pergunta", "frente": "Qual a conduta na suspeita de lesão de coluna no trauma?", "verso": "Restringir o movimento da coluna com alinhamento manual, colar cervical e prancha ou maca adequada, conforme o protocolo.", "explicacao": "Evitar movimentos de flexão e rotação."}, {"id": 2000004913, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Uma bomba de infusão deve correr 1.000 mL em 24 horas. Qual a vazão?", "verso": "Cerca de 41,7 mL/h.", "explicacao": "1.000 ÷ 24."}, {"id": 2000004914, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição de 1.500.000 UI de penicilina G benzatina. Frasco de 1.200.000 UI reconstituído com 4 mL. Quanto aspirar?", "verso": "5 mL (1 frasco e 1 mL de outro frasco).", "explicacao": "1.200.000 ─ 4 mL; 1.500.000 ─ x; x = 5 mL."}, {"id": 2000004915, "trilha": "saude", "materia": "enf", "assunto": "Cálculos", "tipo": "pergunta", "frente": "Prescrição de 8 UI de insulina NPH com seringa de 100 UI/mL. Quantos mL?", "verso": "0,08 mL.", "explicacao": "8 ÷ 100. Na seringa de insulina, aspira-se até a marca de 8 unidades."}, {"id": 2000004916, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "O que é a dupla checagem independente?", "verso": "Conferência do medicamento de alta vigilância por dois profissionais, de forma separada, antes de administrar.", "explicacao": "Recomendada para insulina, heparina, quimioterápicos e eletrólitos concentrados."}, {"id": 2000004917, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Qual a via de administração da vacina contra hepatite B no adulto?", "verso": "Intramuscular, no deltoide.", "explicacao": "No bebê, no vasto lateral da coxa."}, {"id": 2000004918, "trilha": "saude", "materia": "enf", "assunto": "Administração de medicamentos", "tipo": "pergunta", "frente": "Qual o músculo preferencial para injeção intramuscular em lactentes?", "verso": "O vasto lateral da coxa.", "explicacao": "Músculo bem desenvolvido e longe de grandes vasos e nervos."}, {"id": 2000004919, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "Como se mede a profundidade de uma ferida cavitária?", "verso": "Com cotonete ou sonda estéril introduzida até o fundo, marcando o ponto na borda e medindo com régua.", "explicacao": "Registrar em centímetros."}, {"id": 2000004920, "trilha": "saude", "materia": "enf", "assunto": "Feridas", "tipo": "pergunta", "frente": "O que são esfacelo e escara?", "verso": "Esfacelo: tecido desvitalizado amarelado e úmido. Escara: necrose seca, escura e endurecida.", "explicacao": "Ambos atrapalham a cicatrização."}, {"id": 2000004921, "trilha": "saude", "materia": "enf", "assunto": "Sondagens", "tipo": "pergunta", "frente": "Qual o volume de água destilada usado para insuflar o balão da sonda vesical de demora, em geral?", "verso": "Conforme indicado na sonda, geralmente 10 mL de água destilada.", "explicacao": "Não usar soro fisiológico, que pode cristalizar."}, {"id": 2000004922, "trilha": "saude", "materia": "enf", "assunto": "Sondagens", "tipo": "pergunta", "frente": "Como se fixa a sonda vesical de demora no homem?", "verso": "Na região suprapúbica ou no abdome inferior, para evitar fístula penoescrotal.", "explicacao": "Na mulher, na face interna da coxa."}, {"id": 2000004923, "trilha": "saude", "materia": "enf", "assunto": "Sondagens", "tipo": "pergunta", "frente": "Quais os cuidados para prevenir infecção urinária associada à sonda vesical?", "verso": "Técnica asséptica na inserção, sistema fechado, bolsa abaixo da bexiga, higiene diária do meato e retirada assim que possível.", "explicacao": "Bundle de prevenção."}, {"id": 2000004924, "trilha": "saude", "materia": "enf", "assunto": "Coleta de exames", "tipo": "pergunta", "frente": "Qual o jejum recomendado para glicemia de jejum?", "verso": "8 horas.", "explicacao": "Para perfil lipídico, o jejum pode não ser obrigatório, conforme o laboratório."}, {"id": 2000004925, "trilha": "saude", "materia": "enf", "assunto": "Coleta de exames", "tipo": "pergunta", "frente": "Por que não se deve deixar o garrote por muito tempo na coleta de sangue?", "verso": "Porque causa hemoconcentração e altera resultados, como potássio e proteínas.", "explicacao": "Recomenda-se no máximo 1 minuto."}, {"id": 2000004926, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Quais as consultas de puericultura no primeiro ano de vida recomendadas pelo Ministério da Saúde?", "verso": "Na primeira semana, com 1, 2, 4, 6, 9 e 12 meses.", "explicacao": "Calendário mínimo de consultas."}, {"id": 2000004927, "trilha": "saude", "materia": "enf", "assunto": "Saúde da criança", "tipo": "pergunta", "frente": "Para que serve a Caderneta da Criança?", "verso": "Acompanhar o crescimento, o desenvolvimento e a vacinação da criança.", "explicacao": "Inclui curvas de peso, altura e IMC."}, {"id": 2000004928, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "O que é o DIU de cobre e por quanto tempo protege?", "verso": "Dispositivo intrauterino sem hormônio, que pode proteger por cerca de 10 anos.", "explicacao": "Disponível no SUS; enfermeiros capacitados podem inserir."}, {"id": 2000004929, "trilha": "saude", "materia": "enf", "assunto": "Saúde da mulher", "tipo": "pergunta", "frente": "Qual método contraceptivo também protege contra ISTs?", "verso": "O preservativo (masculino ou feminino).", "explicacao": "Recomenda-se dupla proteção."}, {"id": 2000004930, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Qual a altura uterina esperada com 20 semanas de gestação?", "verso": "Na altura da cicatriz umbilical.", "explicacao": "Entre 18 e 30 semanas, a altura em cm é próxima da idade gestacional."}, {"id": 2000004931, "trilha": "saude", "materia": "enf", "assunto": "Obstetrícia", "tipo": "pergunta", "frente": "Quando a gestante deve procurar a maternidade?", "verso": "Perda de líquido, sangramento, contrações regulares e dolorosas, diminuição dos movimentos do bebê, dor de cabeça forte ou visão turva.", "explicacao": "Sinais de alerta."}, {"id": 2000004932, "trilha": "saude", "materia": "enf", "assunto": "Saúde do idoso", "tipo": "pergunta", "frente": "Que orientações ajudam a evitar quedas em casa?", "verso": "Retirar tapetes soltos, instalar barras no banheiro, manter boa iluminação, usar calçados fechados e antiderrapantes e evitar levantar rapidamente.", "explicacao": "Prevenção de quedas."}, {"id": 2000004933, "trilha": "saude", "materia": "enf", "assunto": "Doenças infecciosas", "tipo": "pergunta", "frente": "Quanto tempo de tratamento é necessário para a pessoa com tuberculose deixar de transmitir, em geral?", "verso": "Cerca de 15 dias de tratamento regular.", "explicacao": "Mas deve completar os 6 meses."}, {"id": 2000004934, "trilha": "saude", "materia": "enf", "assunto": "Doenças infecciosas", "tipo": "pergunta", "frente": "Qual o tratamento da hanseníase e por quanto tempo?", "verso": "Poliquimioterapia: 6 doses na paucibacilar e 12 doses na multibacilar, com a PQT-U (rifampicina, dapsona e clofazimina).", "explicacao": "Gratuito no SUS."}, {"id": 2000004935, "trilha": "saude", "materia": "enf", "assunto": "Doenças infecciosas", "tipo": "pergunta", "frente": "Qual a classificação da dengue com sinais de alarme?", "verso": "Grupo C: dengue com sinais de alarme, que exige hidratação venosa e observação em leito.", "explicacao": "Grupo D: dengue grave."}, {"id": 2000004936, "trilha": "saude", "materia": "enf", "assunto": "Doenças crônicas", "tipo": "pergunta", "frente": "Que cuidados orientar sobre a insulina em casa?", "verso": "Guardar na geladeira (fora do congelador), o frasco em uso pode ficar em temperatura ambiente por cerca de 4 semanas, fazer rodízio de locais e descartar agulhas em recipiente rígido.", "explicacao": "Seguir a orientação do fabricante."}, {"id": 2000004937, "trilha": "saude", "materia": "enf", "assunto": "Doenças crônicas", "tipo": "pergunta", "frente": "O que é o autoexame dos pés no diabetes?", "verso": "Olhar os pés todos os dias em busca de feridas, rachaduras, calos ou mudanças de cor, usando espelho se necessário.", "explicacao": "Prevenção do pé diabético."}, {"id": 2000004938, "trilha": "saude", "materia": "enf", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "O que é a abordagem da redução de danos?", "verso": "Estratégia que busca diminuir os prejuízos do uso de drogas sem exigir a abstinência como condição para o cuidado.", "explicacao": "Adotada pela política do SUS."}, {"id": 2000004939, "trilha": "saude", "materia": "enf", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é a supervisão de enfermagem?", "verso": "Processo educativo e de acompanhamento do trabalho da equipe, orientando e avaliando a qualidade da assistência.", "explicacao": "Atribuição do enfermeiro."}, {"id": 2000004940, "trilha": "saude", "materia": "enf", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é a escala de trabalho mensal?", "verso": "Documento que distribui os profissionais por turnos e folgas, conforme o dimensionamento e a legislação.", "explicacao": "Elaborada pelo enfermeiro responsável."}, {"id": 2000004941, "trilha": "saude", "materia": "enf", "assunto": "Educação em saúde", "tipo": "pergunta", "frente": "O que é educação em saúde na enfermagem?", "verso": "Ações de ensino com a população para promover autonomia no cuidado com a saúde, valorizando o saber das pessoas.", "explicacao": "Base na pedagogia de Paulo Freire."}, {"id": 2000004942, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pares", "frente": "Qual a diferença entre afebril, febrícula e febre?", "verso": "Afebril: sem febre. Febrícula: temperatura levemente elevada (cerca de 37,3 a 37,7 °C axilar). Febre: acima de 37,8 °C.", "explicacao": "Faixas variam entre referências."}, {"id": 2000004943, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pergunta", "frente": "O que é diaforese?", "verso": "Sudorese excessiva.", "explicacao": "Comum no infarto e na hipoglicemia."}, {"id": 2000004944, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pergunta", "frente": "O que é hemiparesia?", "verso": "Fraqueza (perda parcial da força) de um lado do corpo.", "explicacao": "Hemiplegia é a perda total."}, {"id": 2000004945, "trilha": "saude", "materia": "enf", "assunto": "Terminologia", "tipo": "pergunta", "frente": "O que é algia e cefalalgia?", "verso": "Algia: dor. Cefalalgia: dor de cabeça.", "explicacao": "Sufixo \"-algia\" indica dor."}, {"id": 2000004946, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Saúde da Pessoa com Deficiência?", "verso": "Política que busca a inclusão da pessoa com deficiência na rede de serviços, com reabilitação e prevenção de agravos.", "explicacao": "Portaria 1.060/2002."}, {"id": 2000004947, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Saúde do Trabalhador e da Trabalhadora?", "verso": "Política que define princípios e estratégias para a atenção integral à saúde do trabalhador, com ênfase na vigilância.", "explicacao": "Portaria 1.823/2012."}, {"id": 2000004948, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Saúde Mental?", "verso": "Política baseada na reforma psiquiátrica, que substituiu os hospitais psiquiátricos por uma rede de serviços comunitários.", "explicacao": "Lei 10.216/2001."}, {"id": 2000004949, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Saúde Bucal (Brasil Sorridente)?", "verso": "Política que amplia o acesso ao tratamento odontológico no SUS, com equipes de saúde bucal e Centros de Especialidades Odontológicas (CEO).", "explicacao": "Lei 14.572/2023 incluiu a saúde bucal na Lei 8.080."}, {"id": 2000004950, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é a Política Nacional de Atenção Integral à Saúde da Criança (PNAISC)?", "verso": "Política que organiza o cuidado da criança do nascimento aos 9 anos, com foco no desenvolvimento integral.", "explicacao": "Portaria 1.130/2015."}, {"id": 2000004951, "trilha": "saude", "materia": "sus", "assunto": "Políticas", "tipo": "pergunta", "frente": "O que é o Programa Nacional de Imunizações (PNI)?", "verso": "Programa do Ministério da Saúde, criado em 1973, que coordena a vacinação no país.", "explicacao": "Referência mundial."}, {"id": 2000004952, "trilha": "saude", "materia": "sus", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é o Sistema Nacional de Auditoria do SUS?", "verso": "Sistema que avalia a gestão técnica, financeira e patrimonial do SUS, com o Denasus como componente federal.", "explicacao": "Lei 8.689/1993."}, {"id": 2000004953, "trilha": "saude", "materia": "sus", "assunto": "Gestão", "tipo": "pergunta", "frente": "O que é o Cebas na saúde?", "verso": "Certificação de entidade beneficente de assistência social, que garante imunidade das contribuições sociais a entidades que prestam serviços ao SUS.", "explicacao": "LC 187/2021."}, {"id": 2000004954, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é a Unidade de Saúde da Família fluvial?", "verso": "UBS em embarcação, que atende populações ribeirinhas da Amazônia e do Pantanal.", "explicacao": "Modalidade prevista na PNAB."}, {"id": 2000004955, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é o acolhimento na atenção básica?", "verso": "Postura e prática de escuta qualificada das necessidades do usuário em todos os momentos, com resposta adequada e responsável.", "explicacao": "Diretriz da Política Nacional de Humanização."}, {"id": 2000004956, "trilha": "saude", "materia": "sus", "assunto": "Atenção primária", "tipo": "pergunta", "frente": "O que é o apoio matricial?", "verso": "Suporte técnico de especialistas às equipes de referência, com discussão de casos e atendimentos conjuntos.", "explicacao": "Ex.: saúde mental na atenção básica."}, {"id": 2000004957, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é a vigilância sentinela?", "verso": "Monitoramento feito em unidades selecionadas para acompanhar a ocorrência de um agravo, como a síndrome gripal.", "explicacao": "Fornece dados representativos."}, {"id": 2000004958, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é quarentena e isolamento?", "verso": "Isolamento: separar pessoas doentes. Quarentena: restringir pessoas expostas, mas ainda sem sintomas, durante o período de incubação.", "explicacao": "Medidas de controle de doenças transmissíveis."}, {"id": 2000004959, "trilha": "saude", "materia": "sus", "assunto": "Vigilância", "tipo": "pergunta", "frente": "O que é a Rede Cievs?", "verso": "Rede de Centros de Informações Estratégicas em Vigilância em Saúde, que detecta e responde a emergências de saúde pública.", "explicacao": "Monitora eventos 24 horas."}, {"id": 2000004960, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é taxa de ataque?", "verso": "Incidência acumulada em uma população durante um surto, em curto período.", "explicacao": "Usada na investigação de surtos."}, {"id": 2000004961, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é a razão de chances (odds ratio)?", "verso": "Medida de associação usada em estudos caso-controle, que compara as chances de exposição entre casos e controles.", "explicacao": "OR > 1 sugere associação positiva."}, {"id": 2000004962, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é viés de seleção?", "verso": "Erro causado pela forma como os participantes foram escolhidos, tornando a amostra não representativa.", "explicacao": "Compromete a validade do estudo."}, {"id": 2000004963, "trilha": "saude", "materia": "sus", "assunto": "Epidemiologia", "tipo": "pergunta", "frente": "O que é fator de confusão?", "verso": "Variável associada à exposição e ao desfecho, que distorce a relação entre eles.", "explicacao": "Ex.: idade em estudos de doenças crônicas."}, {"id": 2000004964, "trilha": "saude", "materia": "sus", "assunto": "Direitos", "tipo": "pergunta", "frente": "A pessoa usuária do SUS tem direito a escolher o profissional que a atende?", "verso": "Tem direito a atendimento humanizado e a informações sobre o profissional; a escolha depende da organização do serviço e da disponibilidade.", "explicacao": "Carta dos Direitos e Deveres da Pessoa Usuária da Saúde."}, {"id": 2000004965, "trilha": "saude", "materia": "sus", "assunto": "Direitos", "tipo": "pergunta", "frente": "Qual lei garante tratamento oncológico pelo SUS em até 60 dias após o diagnóstico?", "verso": "A Lei 12.732/2012.", "explicacao": "Prazo contado a partir do diagnóstico em laudo patológico."}, {"id": 2000004966, "trilha": "saude", "materia": "sus", "assunto": "Direitos", "tipo": "pergunta", "frente": "O que é a Lei do Acompanhante para pessoas idosas internadas?", "verso": "O Estatuto da Pessoa Idosa garante acompanhante em tempo integral ao idoso internado ou em observação.", "explicacao": "Lei 10.741/2003, art. 16."}, {"id": 2000004967, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "Qual o valor normal de frequência cardíaca e de pressão arterial em adultos em repouso?", "verso": "FC entre 60 e 100 bpm; PA ótima abaixo de 120 por 80 mmHg.", "explicacao": "Diretrizes brasileiras de hipertensão."}, {"id": 2000004968, "trilha": "saude", "materia": "med", "assunto": "Cardiologia", "tipo": "pergunta", "frente": "O que é a angina estável?", "verso": "Dor no peito que surge com o esforço e melhora com repouso ou nitrato, por estreitamento das coronárias.", "explicacao": "A instável ocorre em repouso ou piora rapidamente."}, {"id": 2000004969, "trilha": "saude", "materia": "med", "assunto": "Respiratório", "tipo": "pergunta", "frente": "O que é a pneumonia aspirativa e quem tem maior risco?", "verso": "Pneumonia causada pela entrada de conteúdo da boca ou do estômago nos pulmões; maior risco em idosos com disfagia, pessoas com rebaixamento da consciência e uso de sondas.", "explicacao": "Prevenção: cabeceira elevada e avaliação da deglutição."}, {"id": 2000004970, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "Quais os sinais de desidratação no adulto?", "verso": "Sede, boca seca, urina escura e em pouca quantidade, tontura e, nos casos graves, hipotensão e confusão.", "explicacao": "Idosos sentem menos sede."}, {"id": 2000004971, "trilha": "saude", "materia": "med", "assunto": "Gastroenterologia", "tipo": "pergunta", "frente": "O que é a diarreia aguda e qual a principal complicação?", "verso": "Aumento do número de evacuações líquidas por menos de 14 dias; a principal complicação é a desidratação.", "explicacao": "Tratar com soro de reidratação oral."}, {"id": 2000004972, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o principal tratamento da malária por Plasmodium vivax no Brasil?", "verso": "Cloroquina associada à primaquina (esta para eliminar as formas hepáticas).", "explicacao": "A primaquina exige cuidado em gestantes e na deficiência de G6PD."}, {"id": 2000004973, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Como se previne a transmissão vertical do HIV?", "verso": "Pré-natal com testagem, uso de antirretrovirais pela gestante, AZT no parto quando indicado, profilaxia no bebê e não amamentar.", "explicacao": "Reduz a transmissão a menos de 1%."}, {"id": 2000004974, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "Qual o tratamento da sífilis congênita?", "verso": "Penicilina (cristalina ou procaína) por 10 dias, conforme a avaliação do recém-nascido.", "explicacao": "Notificação compulsória."}, {"id": 2000004975, "trilha": "saude", "materia": "med", "assunto": "Infectologia", "tipo": "pergunta", "frente": "O que é a mpox e como se transmite?", "verso": "Doença viral com lesões na pele e mucosas, transmitida principalmente por contato próximo com lesões, fluidos ou objetos contaminados.", "explicacao": "Notificação compulsória."}, {"id": 2000004976, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a doença de Parkinson e qual a base do tratamento?", "verso": "Doença degenerativa com perda de neurônios de dopamina, causando tremor de repouso, rigidez e lentidão. O tratamento usa levodopa.", "explicacao": "Fisioterapia ajuda na marcha e no equilíbrio."}, {"id": 2000004977, "trilha": "saude", "materia": "med", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a paralisia facial periférica (de Bell)?", "verso": "Fraqueza súbita de um lado da face, incluindo a testa, por lesão do nervo facial.", "explicacao": "No AVC, a testa costuma ser poupada."}, {"id": 2000004978, "trilha": "saude", "materia": "med", "assunto": "Endocrinologia", "tipo": "pergunta", "frente": "Quais os sinais de hipertireoidismo?", "verso": "Perda de peso, taquicardia, tremores, intolerância ao calor, sudorese e irritabilidade.", "explicacao": "A doença de Graves é a causa mais comum."}, {"id": 2000004979, "trilha": "saude", "materia": "med", "assunto": "Nefrologia", "tipo": "pergunta", "frente": "O que é a pielonefrite?", "verso": "Infecção urinária que atinge os rins, com febre, dor lombar e sinal de Giordano positivo.", "explicacao": "Exige antibiótico e avaliação médica."}, {"id": 2000004980, "trilha": "saude", "materia": "med", "assunto": "Hematologia", "tipo": "pergunta", "frente": "Qual o valor normal de hemoglobina em adultos?", "verso": "Em geral, 13 a 17 g/dL nos homens e 12 a 15,5 g/dL nas mulheres.", "explicacao": "Varia conforme o laboratório."}, {"id": 2000004981, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Quais os sinais de intoxicação aguda por álcool?", "verso": "Fala arrastada, incoordenação, vômitos, sonolência e, nos casos graves, depressão respiratória e coma.", "explicacao": "Risco de broncoaspiração: lateralizar."}, {"id": 2000004982, "trilha": "saude", "materia": "med", "assunto": "Saúde mental", "tipo": "pergunta", "frente": "Qual o principal fator de risco para suicídio?", "verso": "Tentativa anterior de suicídio.", "explicacao": "Também transtornos mentais, uso de substâncias e isolamento."}, {"id": 2000004983, "trilha": "saude", "materia": "med", "assunto": "Geriatria", "tipo": "pergunta", "frente": "O que é a avaliação geriátrica ampla?", "verso": "Avaliação multidimensional do idoso: funcionalidade, cognição, humor, mobilidade, nutrição, medicamentos e suporte social.", "explicacao": "Orienta o plano de cuidado."}, {"id": 2000004984, "trilha": "saude", "materia": "med", "assunto": "Oncologia", "tipo": "pergunta", "frente": "O que é a quimioterapia e qual efeito adverso comum?", "verso": "Tratamento com medicamentos que destroem células de divisão rápida; efeitos comuns: náuseas, queda de cabelo e queda das defesas (neutropenia).", "explicacao": "Neutropenia febril é emergência."}, {"id": 2000004985, "trilha": "saude", "materia": "med", "assunto": "Pediatria", "tipo": "pergunta", "frente": "Quais os sinais de desidratação grave na criança com diarreia?", "verso": "Letargia, olhos muito fundos, não consegue beber e sinal da prega que volta muito lentamente.", "explicacao": "Plano C: hidratação venosa."}, {"id": 2000004986, "trilha": "saude", "materia": "med", "assunto": "Ética", "tipo": "pergunta", "frente": "O médico pode prescrever sem examinar o paciente?", "verso": "Não, salvo em situações de urgência ou impossibilidade comprovada, ou na telemedicina regulamentada.", "explicacao": "Código de Ética Médica, art. 37."}, {"id": 2000004987, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é a fisioterapia na fibrose cística?", "verso": "Técnicas diárias de higiene brônquica (desobstrução) e exercícios, para manter as vias aéreas livres e a função pulmonar.", "explicacao": "Tratamento contínuo."}, {"id": 2000004988, "trilha": "saude", "materia": "fisio", "assunto": "Respiratória", "tipo": "pergunta", "frente": "O que é o desmame da ventilação mecânica?", "verso": "Processo de retirada gradual do suporte ventilatório até a extubação.", "explicacao": "Inclui o teste de respiração espontânea."}, {"id": 2000004989, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a marcha ceifante?", "verso": "Marcha do hemiplégico em que a perna afetada faz um semicírculo para fora, por espasticidade e dificuldade de dobrar o joelho.", "explicacao": "Comum após AVC."}, {"id": 2000004990, "trilha": "saude", "materia": "fisio", "assunto": "Neurologia", "tipo": "pergunta", "frente": "O que é a marcha festinante?", "verso": "Marcha com passos curtos e acelerados, tronco inclinado para frente e dificuldade de parar, típica da doença de Parkinson.", "explicacao": "Pistas visuais e auditivas ajudam."}, {"id": 2000004991, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a osteoartrite (artrose)?", "verso": "Desgaste da cartilagem articular, com dor, rigidez matinal curta e limitação de movimento, comum em joelhos e quadris.", "explicacao": "Exercício é parte essencial do tratamento."}, {"id": 2000004992, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a lombalgia mecânica inespecífica?", "verso": "Dor lombar sem causa específica identificável, que piora com o movimento e melhora com repouso relativo.", "explicacao": "A maioria melhora em semanas com atividade orientada."}, {"id": 2000004993, "trilha": "saude", "materia": "fisio", "assunto": "Ortopedia", "tipo": "pergunta", "frente": "O que é a síndrome do impacto do ombro?", "verso": "Compressão dos tendões do manguito rotador sob o acrômio ao elevar o braço, com dor e limitação.", "explicacao": "Testes de Neer e Hawkins positivos."}, {"id": 2000004994, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "O que é a estimulação precoce?", "verso": "Programa de intervenção em bebês com risco ou atraso no desenvolvimento, para favorecer as aquisições motoras e cognitivas.", "explicacao": "Quanto antes, melhores os resultados."}, {"id": 2000004995, "trilha": "saude", "materia": "fisio", "assunto": "Pediatria", "tipo": "pergunta", "frente": "O que é a síndrome de Down do ponto de vista motor?", "verso": "Condição genética com hipotonia muscular e frouxidão ligamentar, que atrasam os marcos motores.", "explicacao": "Fisioterapia desde cedo."}, {"id": 2000004996, "trilha": "saude", "materia": "fisio", "assunto": "Geriatria", "tipo": "pergunta", "frente": "O que é a síndrome do imobilismo?", "verso": "Conjunto de complicações do repouso prolongado no leito: perda de força, contraturas, lesões por pressão, trombose, pneumonia e perda de condicionamento.", "explicacao": "Mobilização precoce previne."}, {"id": 2000004997, "trilha": "saude", "materia": "fisio", "assunto": "Oncologia", "tipo": "pergunta", "frente": "Qual a importância do exercício durante o tratamento do câncer?", "verso": "Reduz a fadiga, preserva a força e a funcionalidade e melhora a qualidade de vida.", "explicacao": "Deve ser orientado conforme o tratamento."}, {"id": 2000004998, "trilha": "saude", "materia": "fisio", "assunto": "Dermatofuncional", "tipo": "pergunta", "frente": "Qual a atuação da fisioterapia no paciente queimado?", "verso": "Posicionamento antideformidade, exercícios, controle de cicatrizes hipertróficas com malhas compressivas e prevenção de contraturas.", "explicacao": "Atuação desde a fase aguda."}, {"id": 2000004999, "trilha": "saude", "materia": "fisio", "assunto": "UTI", "tipo": "pergunta", "frente": "O que é a mobilização precoce na UTI?", "verso": "Exercícios e atividades funcionais iniciadas assim que o paciente está estável, para reduzir a fraqueza adquirida na UTI.", "explicacao": "Encurta tempo de internação."}, {"id": 2000005000, "trilha": "saude", "materia": "fisio", "assunto": "UTI", "tipo": "pergunta", "frente": "O que é a fraqueza muscular adquirida na UTI?", "verso": "Fraqueza generalizada que surge durante a doença crítica, ligada ao imobilismo, sepse e alguns medicamentos.", "explicacao": "Avaliada pelo escore MRC."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
